    'ops_policy_schedules_hint' => 'গ্লোবাল রেট কমিশন স্টুডিওতেও লাইভ সম্পাদনা করা যায়। বায়ার স্কোপ এক ডিলার/সাব-ডিলার প্ল্যান সম্পূর্ণ কাস্টমাইজ করে; রেসিপিয়েন্ট স্কোপ শুধু সেই পার্টনারের আয় ক্যাটাগরি সমন্বয় করে। অর্ডার অনুমোদনে সূচি কার্যকর হয়। রেসিপিয়েন্ট রেট বাড়তে বা কমতে পারে; বৃদ্ধির জন্য কোম্পানি-শেয়ার বা নামধারী অ্যালোকেশন ফান্ডিং বেছে নিন। সোর্স কর্তন বৃদ্ধির সাথে মিলতে হবে। হ্রাস রিজার্ভে থাকে। আলাদা ফাইন্যান্স পর্যালোচক প্রতিটি সূচি অনুমোদন করে।',
    'ops_payroll_hint' => 'স্যালারি কন্ট্রাক্ট প্রতিটি সংশোধন সংরক্ষণ করে। অনুমোদনের আগে কন্ট্রাক্ট, টার্গেট ও অর্জিত বোনাস পর্যালোচনা করুন। অনুমোদিত এন্ট্রিতে আলাদা পেয়ার ও ব্যক্তিগত রসিদ প্রয়োজন।',
    'ops_reserve_payouts_hint' => 'ট্যুর রিওয়ার্ড নির্বাচিত সাব-ডিলারের নিজস্ব রিজার্ভ ব্যবহার করে। অনুমোদিত পার্টনার রিওয়ার্ড তাদের আয় ওয়ালেটে জমা হয়। মার্কেটিং খরচে আলাদা পেয়ার, প্রকৃত ব্যাংক/গেটওয়ে রেফারেন্স ও রসিদ প্রয়োজন।',
