    'ops_warn_mail_from_address_is_example_placeholder' => 'MAIL_FROM_ADDRESS এখনও @example.com — গো-লাইভের আগে আসল ফ্রম অ্যাড্রেস সেট করুন।',
    'ops_warn_mail_smtp_host_is_local_development' => 'SMTP হোস্ট লোকাল Mailpit/ডেভ মেইলের মতো — MAIL_HOST প্রোডাকশন মেইলে নির্দেশ করুন।',
    'ops_warn_login_otp_requires_real_sms_before_go_live' => 'লগইন OTP চালু আছে কিন্তু SMS এখনও লগ-অনলি — আসল প্রোভাইডার দিয়ে OTP এন্ড-টু-এন্ড যাচাই করুন।',
    'ops_warn_partner_login_otp_forced_off_in_preview' => 'পার্টনার লগইন OTP সংরক্ষিতভাবে চালু, কিন্তু প্রিভিউ মোড MADINA_PREVIEW_MODE=false ও SMS লাইভ হওয়া পর্যন্ত জোর করে বন্ধ রাখে।',
    'ops_warn_staff_totp_forced_off_in_preview' => 'MADINA_PREVIEW_MODE=true থাকায় স্টাফ/মালিক TOTP চ্যালেঞ্জ জোর করে বন্ধ (প্রিভিউতে SMS/SMTP নেই)।',
    'ops_warn_admin_ip_allowlist_empty' => 'অ্যাডমিন IP অ্যালাউলিস্ট খালি — পাবলিক ইন্টারনেটে manage/sadmin খোলার আগে MADINA_ADMIN_IP_ALLOWLIST সেট করুন।',
    'ops_warn_privacy_retention_unconfigured' => 'প্রাইভেসি রিটেনশন দিন সেট নেই — PDPO গাইডেন্সের জন্য MADINA_PRIVACY_RETENTION_DAYS কনফিগার করুন।',
    'ops_warn_place_code_catalog_incomplete' => 'প্লেস-কোড ক্যাটালগ অসম্পূর্ণ — পার্টনার অনবোর্ডিং গো-লাইভের আগে BangladeshPlaceCodeSeeder চালান (কমপক্ষে ৮টি বিভাগ + ৬৪টি জেলা)।',
    'ops_warn_area_dealer_assignments_missing' => 'সক্রিয় এরিয়া-ডিলার অ্যাসাইনমেন্ট নেই — প্লেস কোড সিডের পর কমপক্ষে একজন বিভাগ/জেলা/উপজেলা/ইউনিয়ন ডিলার সিট করুন, নাহলে ভৌগোলিক কমিশন পুল আনঅ্যাসাইনড রিজার্ভে পোস্ট হবে।',
    'ops_warn_area_dealer_coverage_incomplete' => 'এরিয়া-ডিলার কভারেজ অসম্পূর্ণ — সক্রিয় পার্টনারের বিভাগ/জেলা প্লেসে একক সক্রিয় সিট নেই (বা দ্বৈত/অস্পষ্ট সিট আছে), তাই ভৌগোলিক পুল এখনও আনঅ্যাসাইনড রিজার্ভে পোস্ট হয়।',
    'ops_warn_partners_missing_place_codes' => 'সক্রিয় ডিলার/সাব-ডিলারের place_code নেই — ভৌগোলিক কমিশন গো-লাইভের আগে ক্যাননিকাল প্লেস কোড দিয়ে পুনরায় ইমপোর্ট বা অ্যাকাউন্ট সম্পাদনা করুন।',
    'ops_warn_opening_balances_unverified' => 'উদ্বোধনী ব্যালেন্স দ্বৈত-নিয়ন্ত্রণ যাচাই হয়নি — MADINA_FINANCIAL_ACTIVATION=true করার আগে উদ্বোধনী প্রস্তুত ও যাচাই করুন।',
