    'manual_ch_getting_started_summary' => 'সিস্টেমে প্রথম লগইন, ড্যাশবোর্ড উইজেট, রিয়েল-টাইম মেট্রিক্স, ভাষা পরিবর্তন এবং সামগ্রিক নেভিগেশন কাঠামো বোঝার পূর্ণাঙ্গ নির্দেশিকা।',
    'manual_ch_getting_started_purpose' => 'মদিনা ন্যাচারাল কেয়ার এন্টারপ্রাইজ পোর্টাল হলো ডিলার, সাব-ডিলার, কর্মচারী এবং শীর্ষ ব্যবস্থাপনার মধ্যে সার্বিক ব্যবসা ও আর্থিক সমন্বয় পরিচালনার মূল ডিজিটাল কেন্দ্র। এই প্ল্যাটফর্মের মাধ্যমে স্বচ্ছভাবে পাইকারি অর্ডার, স্বয়ংক্রিয় কমিশন বণ্টন, ডেলিভারি ট্র্যাকিং, ওয়ালেট উত্তোলন এবং দলগত নেটওয়ার্ক পরিচালনা করা হয়।',
    'manual_ch_getting_started_why' => 'ম্যানুয়াল খাতা-কলমের অনিশ্চয়তা, আর্থিক অনিয়ম এবং বিলম্ব দূর করতে এটি একটি অটোমেটেড ক্লাউড আর্কিটেকচার প্রদান করে। প্রতিটি লেনদেনের সম্পূর্ণ ডিজিটাল অডিট ট্রেইল সংরক্ষিত থাকায় ব্যবসার প্রতিটি অংশীদার তাদের ন্যায্য পাওনা তাৎক্ষণিকভাবে দেখতে ও স্বচ্ছতার সাথে নিরীক্ষা করতে পারেন।',
    'manual_ch_getting_started_s1' => 'পোর্টালে আপনার ১১-সংখ্যার নিবন্ধিত মোবাইল নম্বর এবং পাসওয়ার্ড প্রদান করে "লগইন" বাটনে ক্লিক করুন।',
    'manual_ch_getting_started_s2' => 'লগইন সম্পন্ন হলে ড্যাশবোর্ডে প্রবেশের সাথে সাথে প্রথম ভিজিটের জন্য ইন্টারেক্টিভ অনবোর্ডিং লাইভ ট্যুর সক্রিয় হবে; প্রধান উইজেটগুলোর অবস্থান বুঝে নিতে ট্যুরটি সম্পন্ন করুন।',
    'manual_ch_getting_started_s3' => 'ড্যাশবোর্ডের শীর্ষ অংশে মোট কমিশন, উপলব্ধ উত্তোলনযোগ্য ব্যালেন্স, পেন্ডিং অর্ডার এবং বর্তমান পদবী (Rank) প্রদর্শনকারী রিয়েল-টাইম কাউন্টার কার্ডগুলো পর্যালোচনা করুন।',
    'manual_ch_getting_started_s4' => 'পর্দার বাম পাশের নেভিগেশন ড্রয়ার বা সাইডবার মেনু ব্যবহার করে ক্যাটালগ, অর্ডার, ডেলিভারি, কমিশন, নেটওয়ার্ক এবং রিপোর্ট সেকশনে সরাসরি প্রবেশ করুন।',
    'manual_ch_getting_started_s5' => 'শীর্ষ হেডারবারে থাকা ভাষা টগল (বাটন) ব্যবহার করে বাংলা অথবা ইংরেজি ইন্টারফেস বেছে নিন এবং ডার্ক/লাইট মোড নিজের পছন্দমতো সেট করুন।',
    'manual_ch_getting_started_s6' => 'যদি কোনো সেকশনে প্রবেশকালে "প্রিরিকুইজিট চেকলিস্ট" প্রদর্শিত হয়, তবে নির্দেশিত পূর্ববর্তী জরুরি কাজটি (যেমন প্রোফাইল সম্পূর্ণ করা বা পেমেন্ট ভেরিফাই করা) সম্পন্ন করে পুনরায় চেষ্টা করুন।',
    'manual_ch_getting_started_out1' => 'নিরাপদ সেশন টোকেন তৈরি হয় এবং ব্রাউজারে ব্যবহারকারীর ভূমিকাভিত্তিক (Role-Based Access) অনুমোদিত ড্যাশবোর্ড লোড হয়।',
    'manual_ch_getting_started_out2' => 'ড্যাশবোর্ডের সমস্ত আর্থিক কার্ড রিয়েল-টাইম ডাটাবেস ব্যালেন্স শিটের সাথে সিঙ্ক্রোনাইজ হয়ে সর্বশেষ তথ্য প্রদর্শন করে।',
    'manual_ch_getting_started_out3' => 'সিস্টেম অডিট ইভেন্টে সফল লগইন ইভেন্ট, আইপি অ্যাড্রেস এবং ডিভাইসের মেটাডাটা সংরক্ষিত হয়।',
    'manual_ch_getting_started_rule1' => 'একটি অ্যাকাউন্টে একবারে শুধুমাত্র অনুমোদিত ডিভাইস থেকে সেশন পরিচালনা করা যাবে; সন্দেহজনক একাধিক আইপি শনাক্ত হলে অটোমেটিক সিকিউরিটি ফ্ল্যাগ সৃষ্টি হয়।',
    'manual_ch_getting_started_rule2' => 'অ্যাকাউন্টের রোল (যেমন ডিলার বা সাব-ডিলার) পরিবর্তনের অধিকার কেবল ম্যানেজমেন্টের হাতে থাকে।',
    'manual_ch_getting_started_rule3' => 'কোনো ডিলার বা সাব-ডিলারের অ্যাকাউন্ট সাময়িক নিষ্ক্রিয় থাকলে ড্যাশবোর্ডের অর্ডার ও পেআউট সুবিধা স্থগিত থাকবে।',
    'manual_ch_getting_started_t1' => 'প্রথম লগইনের সময় প্রদর্শিত অনবোর্ডিং ট্যুর কোনো কারণে স্কিপ করে ফেললে অ্যাকাউন্ট মেনু থেকে "ইউজার ম্যানুয়াল ও লাইভ ট্যুর" বাটনে ক্লিক করে যেকোনো সময় পুনরায় চালু করতে পারবেন।',
    'manual_ch_getting_started_t2' => 'স্মার্টফোন বা ট্যাবলেটে কাজ করার সময় বাম পাশের ৩-লাইন হ্যামবার্গার মেনুতে ট্যাপ করে সহজে পুরো সাইডবার নেভিগেশন ব্যবহার করুন।',
    'manual_ch_getting_started_warn1' => 'আপনার লগইন ওটিপি বা পাসওয়ার্ড কখনোই কোনো কর্মকর্তা, কর্মচারী বা অন্য কোনো ব্যক্তির সাথে শেয়ার করবেন না।',
    'manual_ch_getting_started_warn2' => 'সাইবার ক্যাফে বা পাবলিক ডিভাইসে লগইন করার পর কাজ শেষে অবশ্যই প্রোফাইল মেনু থেকে "লগআউট" নিশ্চিত করুন।',
    'manual_ch_getting_started_q1' => 'আমি পাসওয়ার্ড ভুলে গেলে কীভাবে পুনরায় লগইন করব?',
    'manual_ch_getting_started_a1' => 'লগইন পেজে "পাসওয়ার্ড ভুলে গেছেন?" লিঙ্কে ক্লিক করে আপনার নিবন্ধিত ফোন নম্বর প্রদান করুন। এসএমএসের মাধ্যমে ওটিপি যাচাই করে নতুন পাসওয়ার্ড নির্ধারণ করুন।',
    'manual_ch_getting_started_q2' => 'ড্যাশবোর্ডের ব্যালেন্স ও তথ্য কি রিয়েল-টাইমে আপডেট হয়?',
    'manual_ch_getting_started_a2' => 'হ্যাঁ, প্রতিটি অর্ডার অনুমোদন, পেমেন্ট ভেরিফিকেশন বা কমিশন বণ্টনের সাথে সাথে ড্যাশবোর্ডের কাউন্টার ও লেজার রিয়েল-টাইমে আপডেট হয়।',
    // Chapter 2: profile_security
    'manual_ch_profile_security_title' => '২. প্রোফাইল ব্যবস্থাপনা, ডিজিটাল আইডি কার্ড ও শপ ভেরিফিকেশন',
    'manual_ch_profile_security_badge' => 'প্রোফাইল ও পরিচয়পত্র',
    'manual_ch_profile_security_summary' => 'ব্যক্তিগত ও বাণিজ্যিক পরিচয়পত্র, দোকান ঠিকানা, এনআইডি/বিডিআরআইএস তথ্য নিশ্চিতকরণ, অফিসিয়াল পার্টনার আইডি কার্ড এবং মার্কেটিং পোস্টার ডাউনলোডের নিয়মাবলী।',
    'manual_ch_profile_security_purpose' => 'প্রোফাইল মডিউলটি পার্টনারদের আইনি পরিচয়, ন্যাশনাল আইডি (NID) বা জন্মনিবন্ধন (BDRIS), ব্যবসায়িক আউটলেট বা দোকানের অবস্থান এবং আর্থিক যোগাযোগের একমাত্র নির্ভরযোগ্য তথ্যকেন্দ্র হিসেবে কাজ করে। এই তথ্যের ভিত্তিতে কোম্পানি পার্টনারদের অফিসিয়াল ডিজিটাল আইডি কার্ড ও কিউআর-কোডযুক্ত পোস্টার ইস্যু করে।',
    'manual_ch_profile_security_why' => 'সঠিক ডিলারশিপ রক্ষা, আঞ্চলিক বিরোধ এড়ানো এবং সরকারের আর্থিক নিয়ন্ত্রণ ও কর নীতি (KYC/AML) প্রতিপালনের জন্য প্রতিটি অ্যাকাউন্টের সম্পূর্ণ প্রোফাইল তথ্য ভেরিফাইড থাকা বাধ্যতামূলক। এটি পার্টনারদের ব্র্যান্ডের অফিসিয়াল বৈধতা প্রদান করে।',
    'manual_ch_profile_security_s1' => 'সাইডবার থেকে "Account" গ্রুপের অধীনে "Profile" সেকশনে ক্লিক করুন।',
    'manual_ch_profile_security_s2' => 'আপনার পূর্ণ নাম, বিকল্প ফোন নম্বর, ইমেইল অ্যাড্রেস, জাতীয় পরিচয়পত্র (NID) নম্বর এবং দোকানের পূর্ণ ভৌগোলিক ঠিকানা নির্ভুলভাবে পূরণ করুন।',
    'manual_ch_profile_security_s3' => 'আপনার দোকানের সাইনবোর্ড বা ট্রেড লাইসেন্স এবং ব্যক্তিগত পাসপোর্ট সাইজ ছবি আপলোড করুন।',
    'manual_ch_profile_security_s4' => '"Save Profile" বাটনে ক্লিক করে তথ্য সংরক্ষণ করুন; সফল সংরক্ষণে একটি গ্রিন অ্যালার্ট প্রদর্শিত হবে।',
    'manual_ch_profile_security_s5' => 'প্রোফাইল পেজের নিচের দিকে স্ক্রল করে "Download Official Partner ID Card" বাটনে ক্লিক করে আপনার অফিসিয়াল পিডিএফে আইডি কার্ড ডাউনলোড করুন।',
    'manual_ch_profile_security_s6' => '"Download Join Poster" বাটনে ক্লিক করে আপনার ব্যক্তিগত রেফারাল কিউআর-কোডসহ উচ্চ রেজোলিউশনের প্রমোশনাল পোস্টার সংগ্রহ করুন।',
    'manual_ch_profile_security_out1' => 'ডাটাবেসে প্রোফাইল রেকর্ড আপডেট হয় এবং সংশ্লিষ্ট অ্যাকাউন্টের অডিট স্ট্যাটাস "KYC Verified" হিসেবে চিহ্নিত হয়।',
    'manual_ch_profile_security_out2' => 'স্বয়ংক্রিয়ভাবে ইউনিক পার্টনার আইডি কার্ড PDF তৈরি হয় যার মধ্যে কিউআর কোড, প্লেস কোড এবং রেজিস্ট্রেশন নম্বর সন্নিবেশিত থাকে।',
    'manual_ch_profile_security_out3' => 'অফিসিয়াল জয়েন পোস্টারে আপনার স্পনসর কোড এনকোড হয় যা স্ক্যান করলেই সরাসরি আপনার ডাউনলাইনে রেজিস্ট্রেশন পেজ খোলে।',
    'manual_ch_profile_security_rule1' => 'নিবন্ধিত মোবাইল নম্বর শুধুমাত্র কোম্পানি অ্যাডমিনের লিখিত অনুমোদন সাপেক্ষে পরিবর্তনযোগ্য।',
    'manual_ch_profile_security_rule2' => 'একই এনআইডি বা জন্মনিবন্ধন নম্বর দিয়ে একাধিক ডিলারশিপ খোলা সম্পূর্ণ নিষিদ্ধ।',
    'manual_ch_profile_security_rule3' => 'দোকানের ঠিকানা অন্য উপজেলায় স্থানান্তরিত হলে অবশ্যই সাপোর্ট টিকেটের মাধ্যমে প্লেস কোড পরিবর্তনের আবেদন করতে হবে।',
    'manual_ch_profile_security_t1' => 'আপনার দোকানে ডাউনলোডকৃত পার্টনার আইডি কার্ড প্রিন্ট করে ঝুলিয়ে রাখুন; এটি গ্রাহকদের মধ্যে আস্থা বৃদ্ধি করে।',
    'manual_ch_profile_security_t2' => 'সোশ্যাল মিডিয়ায় প্রচারের জন্য ডিজিটাল জয়েন পোস্টারটি ব্যবহার করুন যাতে নতুন সাব-ডিলার আপনার কিউআর কোড স্ক্যান করে যুক্ত হতে পারে।',
    'manual_ch_profile_security_warn1' => 'ভুয়া বা অন্যের এনআইডি তথ্য প্রদান করলে আইডি কার্ড বাতিলসহ অ্যাকাউন্ট স্থায়ীভাবে স্থগিত (Banned) করা হবে।',
    'manual_ch_profile_security_warn2' => 'আইডি কার্ডে কোনো রূপ ফটোশপ বা পরিবর্তন করা দণ্ডনীয় অপরাধ।',
    'manual_ch_profile_security_q1' => 'আমি কি আমার দোকানের নাম বা ঠিকানা পরিবর্তন করতে পারি?',
    'manual_ch_profile_security_a1' => 'হ্যাঁ, প্রোফাইল পেজ থেকে দোকানের নাম ও বিস্তারিত ঠিকানা আপডেট করা যাবে। তবে ইউনিয়ন বা উপজেলা বদল হলে প্লেস কোড সমন্বয় প্রয়োজন হবে।',
    'manual_ch_profile_security_q2' => 'আইডি কার্ড ডাউনলোডে সমস্যা হলে কী করণীয়?',
    'manual_ch_profile_security_a2' => 'প্রোফাইলে নাম, ফোন ও ঠিকানা সম্পূর্ণ ফিল্ড পূরণ করা আছে কিনা যাচাই করুন। অসম্পূর্ণ তথ্যে আইডি কার্ড জেনারেট হয় না।',
    // Chapter 3: catalog_orders
    'manual_ch_catalog_orders_title' => '৩. পণ্য ক্যাটালগ ব্রাউজিং, পাইকারি ক্রয় ও কার্ট ব্যবস্থাপনা',
    'manual_ch_catalog_orders_badge' => 'ক্যাটালগ ও ক্রয়',
    'manual_ch_catalog_orders_summary' => 'পাইকারি মূল্য (Wholesale Price) ও এমআরপি মার্জিন পর্যালোচনা, ক্যাটালগে পণ্য বাছাই, কার্ট তৈরি, ক্রয় অনুরোধ ও ইনভয়েস প্রক্রিয়া।',
    'manual_ch_catalog_orders_purpose' => 'ক্যাটালগ ও অর্ডার ইঞ্জিন হলো ডিলার ও সাব-ডিলারদের পণ্য সংগ্রহের মূল পাইপলাইন। এখানে সর্বোচ্চ খুচরা বিক্রয়মূল্য (MRP) এবং পাইকারি ডিলার মূল্যের স্পষ্ট মার্জিন প্রদর্শিত হয়। কার্টের মাধ্যমে একসাথে একাধিক পণ্য যোগ করে একক অর্ডারে রূপান্তর করা যায়।',
    'manual_ch_catalog_orders_why' => 'সরাসরি কোম্পানি থেকে জেনুইন ন্যাচারাল কেয়ার পণ্য সাশ্রয়ী পাইকারি মূল্যে সংগ্রহের সুযোগ দেয়। এটি মধ্যস্বত্বভোগী ছাড়াই ডিলারদের সর্বোচ্চ মুনাফা নিশ্চিত করে এবং প্রতিটি ক্রয়ের ওপর সাথে সাথে চালান ও ইনভয়েস ইস্যু করে।',
    'manual_ch_catalog_orders_s1' => 'সাইডবার মেনু থেকে "Commerce" গ্রুপের অধীনে "Catalog" অপশনে ক্লিক করুন।',
    'manual_ch_catalog_orders_s2' => 'প্রোডাক্ট লিস্টে পণ্যের ছবি, বিবরণ, স্টক স্ট্যাটাস, সর্বোচ্চ খুচরা মূল্য (MRP), আপনার বিশেষ পাইকারি ক্রয়মূল্য এবং সম্ভাব্য লাভের মার্জিন দেখুন।',
    'manual_ch_catalog_orders_s3' => 'প্রয়োজনীয় পণ্যের পাশে পরিমাণ (Quantity) নির্বাচন করে "Add to Cart" বাটনে ক্লিক করুন।',
    'manual_ch_catalog_orders_s4' => 'পর্দার নিচে বা শীর্ষে থাকা কার্ট বারে ক্লিক করে নির্বাচিত পণ্য ও মোট টাকার পরিমাণ রিভিউ করুন।',
    'manual_ch_catalog_orders_s5' => '"Proceed to Checkout" বা "Submit Order Request" বাটনে ক্লিক করে ক্রয়ের অনুরোধটি চূড়ান্ত করুন।',
    'manual_ch_catalog_orders_s6' => 'অর্ডার সাবমিট হওয়ার পর "Orders" সেকশনে গিয়ে আপনার অর্ডার নম্বর (যেমন: ORD-2026-XXXX) এবং স্ট্যাটাস "Pending" দেখতে পাবেন।',
    'manual_ch_catalog_orders_s7' => 'অর্ডারটি ওপেন করে ড্রাফট ইনভয়েস লেটার ডাউনলোড করতে পারবেন (পার্টনারদের কপির ওপর "PARTNER COPY" ওয়াটারমার্ক প্রদর্শিত হয়)।',
    'manual_ch_catalog_orders_out1' => 'ডাটাবেসে নতুন অর্ডার সৃষ্টি হয় এবং একটি ইউনিক আইডেমপোটেন্সি কি (Idempotency Key) যুক্ত হয় যা একই অর্ডারের দুইবার সাবমিট হওয়া রোধ করে।',
    'manual_ch_catalog_orders_out2' => 'অর্ডারের মোট মূল্য এবং অবশিষ্ট দেয় টাকার পরিমাণ স্বয়ংক্রিয়ভাবে "Dues" লেজারে সংরক্ষিত হয়।',
    'manual_ch_catalog_orders_out3' => 'অ্যাকাউন্টস এবং ফুলফিলমেন্ট টিমের ড্যাশবোর্ডে নতুন অর্ডার রিভিউ করার জন্য রিয়েল-টাইম নোটিফিকেশন পৌঁছায়।',
    'manual_ch_catalog_orders_rule1' => 'স্টকে পর্যাপ্ত পণ্য না থাকলে সিস্টেমে অতিরিক্ত পরিমাণের অর্ডার প্লেস করা যাবে না।',
    'manual_ch_catalog_orders_rule2' => 'অর্ডার প্লেস করার পর তা পরিবর্তনের জন্য কোম্পানি অ্যাডমিন বা ডেস্কে যোগাযোগ করতে হবে; সরাসরি ডিলিট করা যায় না।',
    'manual_ch_catalog_orders_rule3' => 'প্রতিটি অর্ডারে কোম্পানির পাইকারি ডিসকাউন্ট নীতি স্বয়ংক্রিয়ভাবে কার্যকর হয়।',
    'manual_ch_catalog_orders_t1' => 'মোবাইলে অর্ডার করার সময় নিচের স্টিকি কার্ট বারটি ব্যবহার করে দ্রুত এক ক্লিকে চেকআউট সম্পন্ন করুন।',
    'manual_ch_catalog_orders_t2' => 'এমআরপি এবং আপনার পাইকারি মূল্যের পার্থক্যটি লক্ষ্য করে খুচরা বিক্রয়ের কৌশল নির্ধারণ করুন।',
    'manual_ch_catalog_orders_warn1' => 'একই অর্ডারের জন্য বারবার সাবমিট বাটনে চাপবেন না; সিস্টেম স্বয়ংক্রিয়ভাবে ডবল অর্ডার রোধ করে তবে ধৈর্য ধরুন।',
    'manual_ch_catalog_orders_warn2' => 'অর্ডার অনুমোদন হওয়ার পূর্বেই গ্রাহকের কাছ থেকে অগ্রিম ডেলিভারির প্রতিশ্রুতি দেওয়া থেকে বিরত থাকুন।',
    'manual_ch_catalog_orders_q1' => 'ইনভয়েস কপিতে ওয়াটারমার্ক কেন থাকে?',
    'manual_ch_catalog_orders_a1' => 'পার্টনারদের কপিতে "PARTNER COPY" ওয়াটারমার্ক থাকে নিরাপত্তার জন্য, যা কোম্পানি অফিশিয়াল রেকর্ড থেকে ডিলার কপিকে পৃথক করে।',
    'manual_ch_catalog_orders_q2' => 'ক্যাটালগে কোনো পণ্য "Out of Stock" দেখালে কী করব?',
    'manual_ch_catalog_orders_a2' => 'সাপোর্ট টিকেটের মাধ্যমে গুদামে নতুন চালান আসার আনুমানিক তারিখ জেনে নিতে পারেন। পণ্য স্টকে এলে পুনরায় অর্ডার সক্রিয় হবে।',
    // Chapter 4: deliveries_dues
    'manual_ch_deliveries_dues_title' => '৪. শিপমেন্ট ট্র্যাকিং, কুরিয়ার চালান ও বকেয়া সমন্বয়',
    'manual_ch_deliveries_dues_badge' => 'লজিস্টিকস ও বাকি',
    'manual_ch_deliveries_dues_summary' => 'অর্ডার অনুমোদন পরবর্তী স্টক ডিসপ্যাচ, কুরিয়ার চালান ট্র্যাকিং (Steadfast, Pathao, RedX), ডেলিভারি নিশ্চিতকরণ এবং বাকি পাওনার সমন্বয় হিসাব।',
    'manual_ch_deliveries_dues_purpose' => 'ডেলিভারি ও বাকি মডিউলটি অর্ডারের শারীরিক পণ্য সরবরাহ এবং আর্থিক দেনা-পাওনার স্বচ্ছ সমন্বয় নিশ্চিত করে। এখানে কুরিয়ার পার্টনারদের ট্র্যাকিং আইডি, কনসাইনমেন্ট স্ট্যাটাস এবং পেমেন্ট ভেরিফিকেশনের পর অবশিষ্ট বকেয়া টাকার নির্ভুল হিসাব সংরক্ষিত থাকে।',
    'manual_ch_deliveries_dues_why' => 'ডেলিভারি বিলম্ব বা পণ্য খোয়া যাওয়া রোধে ডিজিটাল কুরিয়ার ট্র্যাকিং অত্যন্ত গুরুত্বপূর্ণ। এছাড়া অনুমোদিত অর্ডারের পেমেন্ট সমন্বয় করে ডিলারের ক্রেডিট লিমিট ও বকেয়া শূন্য করার মাধ্যমে ব্যবসার গতি অব্যাহত রাখা যায়।',
    'manual_ch_deliveries_dues_s1' => 'সাইডবার থেকে "Deliveries" সেকশনে প্রবেশ করে প্রেরিত অর্ডারের শিপমেন্ট স্ট্যাটাস চেক করুন।',
    'manual_ch_deliveries_dues_s2' => 'কুরিয়ারের নাম (যেমন: Steadfast Courier, Pathao, RedX ইত্যাদি) এবং কনসাইনমেন্ট ট্র্যাকিং কোড দেখতে পাবেন।',
    'manual_ch_deliveries_dues_s3' => 'ট্র্যাকিং লিঙ্কে ক্লিক করে কুরিয়ার পার্টনারের ওয়েবসাইটে পার্সেলের রিয়েল-টাইম অবস্থান পর্যবেক্ষণ করুন।',
    'manual_ch_deliveries_dues_s4' => 'পণ্য হাতে পৌঁছালে পার্সেলের সিল অক্ষত আছে কিনা পরীক্ষা করে ডেলিভারি চালানে স্বাক্ষর করুন।',
    'manual_ch_deliveries_dues_s5' => 'বকেয়া টাকার পরিমাণ দেখার জন্য সাইডবার থেকে "Dues" সেকশনে যান; এখানে মোট ক্রয়, পরিশোধিত টাকা এবং বকেয়া পরিমাণ প্রদর্শিত হবে।',
    'manual_ch_deliveries_dues_s6' => 'বকেয়া পরিশোধ করতে সংশ্লিষ্ট অর্ডারে ক্লিক করে বিকাশ/নগদ/ব্যাংক মাধ্যমে পেমেন্ট করে TrxID ক্লেইম সাবমিট করুন।',
    'manual_ch_deliveries_dues_out1' => 'অর্ডার স্ট্যাটাস "Dispatched" থেকে "Delivered" এ রূপান্তরিত হয় এবং চালানের ডিজিটাল প্রমাণ সিস্টেমে সংযুক্ত হয়।',
    'manual_ch_deliveries_dues_out2' => 'পরিশোধিত পেমেন্ট হিসাবরক্ষক দ্বারা অনুমোদিত হলে অর্ডারের বকেয়া ব্যালেন্স শূন্য (BDT 0.00) হয়।',
    'manual_ch_deliveries_dues_out3' => 'ডিলারের আর্থিক প্রোফাইল ক্লিয়ার থাকে এবং পরবর্তী বড় অর্ডারের জন্য ক্রেডিট অনুমোদন সহজ হয়।',
    'manual_ch_deliveries_dues_rule1' => 'শুধুমাত্র পেমেন্ট ভেরিফাইড অথবা অনুমোদিত ক্রেডিট সীমার মধ্যে থাকা অর্ডারই ডিসপ্যাচের জন্য পাঠানো হয়।',
    'manual_ch_deliveries_dues_rule2' => 'কুরিয়ারে পণ্য ক্ষতিগ্রস্ত হলে পার্সেল গ্রহণ না করে চালানে নোট লিখে অবিলম্বে সাপোর্ট হেল্পডেস্কে জানাতে হবে।',
    'manual_ch_deliveries_dues_rule3' => 'বকেয়া পরিশোধের দাবির সাথে অবশ্যই সঠিক ট্রানজেকশন আইডি (TrxID) বা ব্যাংক জমার রসিদ জমা দিতে হবে।',
    'manual_ch_deliveries_dues_t1' => 'ডেলিভারি চালানের একটি কপি বা ছবি নিজের দোকানে সংরক্ষণ করুন; ভবিষ্যতে যেকোনো অডিট বা মিসম্যাচে এটি কাজে দেবে।',
    'manual_ch_deliveries_dues_t2' => 'Dues সেকশনে নিয়মিত চোখ রাখুন যাতে কোনো অর্ডারের বকেয়া জমে না থাকে এবং পেআউট ব্লক না হয়।',
    'manual_ch_deliveries_dues_warn1' => 'সিলছেঁড়া বা ক্ষতিগ্রস্ত প্যাকেট গ্রহণ করবেন না; সিল খোলা অবস্থায় গ্রহণ করলে কোম্পানি দায়ী থাকবে না।',
    'manual_ch_deliveries_dues_warn2' => 'ভুয়া TrxID দিয়ে বকেয়া পরিশোধের দাবি করলে অ্যাকাউন্ট সাময়িক স্থগিত করা হতে পারে।',
    'manual_ch_deliveries_dues_q1' => 'কুরিয়ার ডেলিভারি বিলম্বিত হলে কী করব?',
    'manual_ch_deliveries_dues_a1' => 'Deliveries পেজে প্রদত্ত ট্র্যাকিং নম্বর দিয়ে কুরিয়ারের পোর্টালে স্ট্যাটাস দেখুন অথবা আমাদের সাপোর্ট টিকেটে অর্ডার নম্বর জানিয়ে মেসেজ দিন।',
    'manual_ch_deliveries_dues_q2' => 'আমি পেমেন্ট করেছি কিন্তু Dues এ বকেয়া দেখাচ্ছে কেন?',
    'manual_ch_deliveries_dues_a2' => 'পেমেন্ট ক্লেইম সাবমিটের পর কোম্পানির ফাইন্যান্স ডেস্ক ব্যাংক স্টেটমেন্ট যাচাই করে অনুমোদন দিলে Dues শূন্য হবে। এটি সাধারণত ১-৩ কার্যঘণ্টা সময় নেয়।',
    // Chapter 5: network_genealogy
    'manual_ch_network_genealogy_title' => '৫. রেফারাল নেটওয়ার্ক, জিনিওলজি ট্রি ও ডাউনলাইন টিম ম্যানেজমেন্ট',
    'manual_ch_network_genealogy_badge' => 'রেফারাল ও দলীয় বৃদ্ধি',
    'manual_ch_network_genealogy_summary' => 'আমন্ত্রণ লিঙ্ক ও কিউআর কোড পোস্টার শেয়ার, মাল্টিলেভেল ডাউনলাইন ট্রি পর্যবেক্ষণ, টিমের পারফরম্যান্স এবং ডেপথ অ্যানালিটিক্স।',
    'manual_ch_network_genealogy_purpose' => 'নেটওয়ার্ক ও জিনিওলজি ইঞ্জিনটি ডিলারদের তাদের নিজস্ব ডিস্ট্রিবিউশন টিম গঠন ও সম্প্রসারণ করার সুযোগ দেয়। এটি স্পনসর করা নতুন ডিলার ও সাব-ডিলারদের অধস্তন কাঠামো (Tree Hierarchy), জেনারেশন লেভেল এবং টিমের সম্মিলিত কেনাকাটার ভলিউম সুবিন্যস্তভাবে প্রদর্শন করে।',
    'manual_ch_network_genealogy_why' => 'একটি শক্তিশালী নেটওয়ার্ক তৈরি করে পরোক্ষ রেফারাল কমিশন এবং পদবীভিত্তিক গ্লোবাল রয়্যালটি অর্জন করা সম্ভব। টিমের সদস্যদের অগ্রগতি পর্যবেক্ষণ করে তাদের উৎসাহ দেওয়া এবং দুর্বল অঞ্চলগুলোতে ডিস্ট্রিবিউশন বাড়ানো যায়।',
    'manual_ch_network_genealogy_s1' => 'সাইডবার থেকে "Network" সেকশনে প্রবেশ করুন।',
    'manual_ch_network_genealogy_s2' => 'আপনার ইউনিক রেফারাল লিঙ্কটি কপি করতে "Copy Invite Link" বাটনে ক্লিক করুন অথবা "Share Join Poster" এ ক্লিক করুন।',
    'manual_ch_network_genealogy_s3' => 'নতুন পার্টনারকে এই লিঙ্কের মাধ্যমে রেজিস্ট্রেশন সম্পূর্ণ করতে বলুন; তারা স্বয়ংক্রিয়ভাবে আপনার সরাসরি স্পনসর হিসেবে যুক্ত হবে।',
    'manual_ch_network_genealogy_s4' => 'জিনিওলজি ট্রি ট্যাবে ক্লিক করে আপনার ডাউনলাইনের বৃক্ষসদৃশ চিত্র (Visual Tree) দেখুন, যেখানে প্রতিটি স্তরের পার্টনারদের অবস্থান দৃশ্যমান।',
    'manual_ch_network_genealogy_s5' => 'যেকোনো নোডে ক্লিক করে সংশ্লিষ্ট ডিলারের নাম, ফোন, যোগদানের তারিখ, সক্রিয় পদবী এবং মোট পার্সোনাল ও টিম সেলস পর্যবেক্ষণ করুন।',
    'manual_ch_network_genealogy_s6' => 'প্রয়োজনে সম্পূর্ণ টিম মেম্বারদের তালিকা অফলাইনে পর্যবেক্ষণের জন্য "Export Directory (CSV)" বাটনে ক্লিক করে এক্সেল ফাইলে সংরক্ষণ করুন।',
    'manual_ch_network_genealogy_out1' => 'নতুন পার্টনার সফলভাবে রেজিস্ট্রেশন করলে ডাটাবেসে রেফারাল ট্রি পাথ (Referral Tree Path) তৈরি হয়।',
    'manual_ch_network_genealogy_out2' => 'ডাউনলাইনের যেকোনো সদস্যের কেনাকাটা অনুমোদিত হওয়া মাত্রই স্পনসর হিসেবে আপনার অ্যাকাউন্টে রেফারাল কমিশন যুক্ত হয়।',
    'manual_ch_network_genealogy_out3' => 'টিমের সম্মিলিত টার্নওভার আপনার পদবী (Rank) এবং রিওয়ার্ড পয়েন্ট অর্জনে সহায়তা করে।',
    'manual_ch_network_genealogy_rule1' => 'একবার কোনো পার্টনার স্পনসর কোড দিয়ে নিবন্ধিত হলে তা পরবর্তীতে অন্য স্পনসরের অধীনে পরিবর্তন করা যায় না।',
    'manual_ch_network_genealogy_rule2' => 'রেফারাল কমিশন পাওয়ার জন্য স্পনসর অ্যাকাউন্টের স্ট্যাটাস "Active" থাকা বাধ্যতামূলক।',
    'manual_ch_network_genealogy_rule3' => 'অনৈতিক উপায়ে বা মিথ্যা প্রলোভন দেখিয়ে ডিলার যুক্ত করা কোম্পানি পলিসির পরিপন্থী।',
    'manual_ch_network_genealogy_t1' => 'আপনার সরাসরি স্পনসরকৃত ডিলারদের সাথে নিয়মিত যোগাযোগ রাখুন এবং পণ্য সম্পর্কিত প্রশিক্ষণ প্রদান করুন।',
    'manual_ch_network_genealogy_t2' => 'টিমের সক্রিয় সদস্যদের পদোন্নতি অর্জনে সহায়তা করুন; তারা নতুন র‍্যাঙ্ক অর্জন করলে আপনার রয়্যালটি পয়েন্ট বৃদ্ধি পাবে।',
    'manual_ch_network_genealogy_warn1' => 'সোশ্যাল মিডিয়ায় অননুমোদিত অফার বা বিভ্রান্তিকর তথ্য দিয়ে স্পনসর প্রচার করা নিষিদ্ধ।',
    'manual_ch_network_genealogy_warn2' => 'স্পনসরবিহীন অ্যাকাউন্টের ক্ষেত্রে কোম্পানি স্বয়ংক্রিয়ভাবে আঞ্চলিক এরিয়া ডিলারের সাথে রেফারেল লিংক নির্ধারণ করতে পারে।',
    'manual_ch_network_genealogy_q1' => 'আমার ডাউনলাইনের কেউ কেনাকাটা করলে আমি কীভাবে জানব?',
    'manual_ch_network_genealogy_a1' => 'ডাউনলাইনের কেনাকাটা অনুমোদিত হলে Earnings সেকশনে সংশ্লিষ্ট অর্ডার নম্বর ও অর্জিত কমিশনের এন্ট্রি রিয়েল-টাইমে প্রদর্শিত হবে।',
    'manual_ch_network_genealogy_q2' => 'জিনিওলজি ট্রিতে কত লেভেল পর্যন্ত দেখা যায়?',
    'manual_ch_network_genealogy_a2' => 'আপনার প্রথম জেনারেশন থেকে শুরু করে সম্পূর্ণ ডাউনলাইনের আনলিমিটেড ডেপথ পর্যন্ত ট্রিব্রিউতে স্ক্রল বা জুম করে দেখা যায়।',
    // Chapter 6: area_dealers_places
    'manual_ch_area_dealers_places_title' => '৬. বাংলাদেশ প্লেস কোড, এরিয়া ডিলার ও আঞ্চলিক এখতিয়ার',
    'manual_ch_area_dealers_places_badge' => 'ভৌগোলিক এখতিয়ার',
    'manual_ch_area_dealers_places_summary' => 'বিভাগ, জেলা, উপজেলা ও ইউনিয়নভিত্তিক ৬-সংখ্যার প্লেস কোড সিস্টেম, এক্সক্লুসিভ এরিয়া ডিলার সুযোগ-সুবিধা এবং আঞ্চলিক ডিস্ট্রিবিউশন প্রটেকশন।',
    'manual_ch_area_dealers_places_purpose' => 'বাংলাদেশ প্লেস কোড আর্কিটেকচার হলো দেশের সমগ্র ভৌগোলিক মানচিত্রকে (বিভাগ > জেলা > উপজেলা > ইউনিয়ন) সুনির্দিষ্ট কোডের মাধ্যমে ডিজিটালাইজড করার ব্যবস্থা। এর মাধ্যমে প্রতিটি ডিলারশিপের জন্য ভৌগোলিক আঞ্চলিক এখতিয়ার (Territorial Exclusivity) নির্ধারণ করা হয়।',
    'manual_ch_area_dealers_places_why' => 'একই এলাকায় ডিলারদের মধ্যে অনাকাঙ্ক্ষিত প্রতিযোগিতা দূর করতে এবং প্রতিটি অঞ্চলে নিয়মতান্ত্রিকভাবে পণ্য সরবরাহ নিশ্চিত করতে এরিয়া ডিলার সিস্টেম অপরিহার্য। এরিয়া ডিলারগণ তাদের এলাকায় সম্পন্ন হওয়া সমস্ত স্থানীয় সেলসের ওপর বিশেষ প্রাতিষ্ঠানিক সুবিধা পান।',
    'manual_ch_area_dealers_places_s1' => 'সাইডবার থেকে "Area Dealers" অথবা প্রোফাইল সেকশন থেকে আপনার নির্ধারিত প্লেস কোডটি (Place Code) দেখুন।',
    'manual_ch_area_dealers_places_s2' => 'প্লেস কোডের প্রথম ২ সংখ্যা বিভাগ, পরবর্তী ২ সংখ্যা জেলা এবং শেষ ২ সংখ্যা উপজেলা/থানা নির্দেশ করে।',
    'manual_ch_area_dealers_places_s3' => 'আপনার ইউনিয়ন বা উপজেলার জন্য কোনো এরিয়া ডিলার নির্ধারিত আছে কিনা তা দেখতে প্লেস কোড ডিরেক্টরি সার্চ করুন।',
    'manual_ch_area_dealers_places_s4' => 'যদি আপনি নির্দিষ্ট উপজেলার একমাত্র এরিয়া ডিলার হতে চান, তবে নির্ধারিত বিনিয়োগ ও সেলস ক্রাইটেরিয়া পূরণ করে ম্যানেজমেন্ট বরাবর আবেদন করুন।',
    'manual_ch_area_dealers_places_s5' => 'এরিয়া ডিলার হিসেবে অনুমোদিত হলে আপনার অঞ্চলের অন্যান্য সাব-ডিলারদের অর্ডার সাপ্লাই ও ডেলিভারি অগ্রাধিকার আপনার মাধ্যমে পরিচালিত হবে।',
    'manual_ch_area_dealers_places_s6' => 'আঞ্চলিক কোনো বিরোধ সৃষ্টি হলে প্লেস কোড ভিত্তিক সীমানা ম্যাপিং পর্যালোচনা করতে সাপোর্ট টিকেটে যোগাযোগ করুন।',
    'manual_ch_area_dealers_places_out1' => 'ডিলারের অ্যাকাউন্টের সাথে প্লেস কোড ম্যাপ হয় এবং সিস্টেম সেই অঞ্চলের অর্ডারগুলোতে আঞ্চলিক অগ্রাধিকার সক্রিয় করে।',
    'manual_ch_area_dealers_places_out2' => 'সংশ্লিষ্ট প্লেস কোডের আওতাধীন সাব-ডিলারদের কেনাকাটা স্বয়ংক্রিয়ভাবে এরিয়া ডিলারের কোটার সাথে লিঙ্ক হয়।',
    'manual_ch_area_dealers_places_out3' => 'ডিলার ডিরেক্টরিতে আপনার দোকান ওই উপজেলার অফিশিয়াল ডিস্ট্রিবিউশন পয়েন্ট হিসেবে প্রদর্শিত হয়।',
    'manual_ch_area_dealers_places_rule1' => 'প্রতিটি উপজেলা বা থানায় কোম্পানি নীতিমালা অনুযায়ী সীমিত সংখ্যক অনুমোদিত এরিয়া ডিলার নিয়োগ দেওয়া হয়।',
    'manual_ch_area_dealers_places_rule2' => 'এরিয়া ডিলারশিপ কার্যকর রাখতে প্রতি মাসে নির্ধারিত ন্যূনতম আঞ্চলিক সেলস টার্নওভার বজায় রাখা বাধ্যতামূলক।',
    'manual_ch_area_dealers_places_rule3' => 'অন্য অঞ্চলের ডিলারের সীমানায় গিয়ে অননুমোদিত পাইকারি সাপ্লাই দেওয়া শৃঙ্খলাভঙ্গের শামিল।',
    'manual_ch_area_dealers_places_t1' => 'আপনার উপজেলার নতুন দোকানদার ও সাব-ডিলারদের সাথে সুসম্পর্ক গড়ে তুলুন যাতে তারা আপনার মাধ্যমেই নিয়মিত পণ্য সংগ্রহ করে।',
    'manual_ch_area_dealers_places_t2' => 'ইউনিয়ন ভিত্তিক প্লেস কোডটি মনে রাখুন; যেকোনো নতুন ডিলার যুক্ত করার সময় সঠিক প্লেস কোড নির্বাচন করা জরুরি।',
    'manual_ch_area_dealers_places_warn1' => 'ভুল প্লেস কোড প্রদান করলে আপনার কমিশন ও শিপমেন্ট ভুল অঞ্চলে চলে যেতে পারে।',
    'manual_ch_area_dealers_places_warn2' => 'টানা তিন মাস কোটা অর্জনে ব্যর্থ হলে কোম্পানি ওই অঞ্চলের এরিয়া ডিলারশিপ অন্য যোগ্য ডিলারকে অর্পণ করতে পারে।',
    'manual_ch_area_dealers_places_q1' => 'আমি কীভাবে আমার প্লেস কোড জানতে পারব?',
    'manual_ch_area_dealers_places_a1' => 'আপনার প্রোফাইল পেজে অথবা আইডি কার্ডের নিচের অংশে ৬-সংখ্যার প্লেস কোডটি সুস্পষ্টভাবে উল্লেখিত রয়েছে।',
    'manual_ch_area_dealers_places_q2' => 'একই উপজেলায় কি একাধিক এরিয়া ডিলার থাকতে পারে?',
    'manual_ch_area_dealers_places_a2' => 'সাধারণত বড় উপজেলায় ইউনিয়ন ভিত্তিক একাধিক ডিলার থাকতে পারে, তবে নির্দিষ্ট ইউনিয়নের জন্য একজন ডিলারই এক্সক্লুসিভ থাকেন।',
    // Chapter 7: commissions_pool
    'manual_ch_commissions_pool_title' => '৭. কমিশন আর্কিটেকচার, ৪০/৬০ পলিসি ও রিয়েল-টাইম আর্নিং লেজার',
    'manual_ch_commissions_pool_badge' => 'কমিশন ও আর্থিক ইঞ্জিন',
    'manual_ch_commissions_pool_summary' => 'কোম্পানির ৪০% পার্টনার ডিস্ট্রিবিউশন পুল ও ৬০% রিটেইন্ড ক্যাপিটাল আর্কিটেকচার, রেফারাল বোনাস, জেনারেশন কমিশন এবং গাণিতিক অডিট প্রমাণ।',
    'manual_ch_commissions_pool_purpose' => 'কমিশন ইঞ্জিনটি মদিনা ন্যাচারাল কেয়ারের আর্থিক বণ্টনের মূল চালিকাশক্তি। প্রতিটি অনুমোদিত অর্ডারের মোট ক্যাশ ইনফ্লোকে গাণিতিকভাবে বিভক্ত করা হয়: ৬০% কোম্পানির উৎপাদন ও পরিচালন মূলধন ফান্ডে সংরক্ষিত হয় এবং ৪০% অর্থ সরাসরি পার্টনার কমিশন পুলে জমা হয়ে রেফারাল, জেনারেশন ও রয়্যালটিতে বণ্টিত হয়।',
    'manual_ch_commissions_pool_why' => 'সম্পূর্ণ স্বচ্ছ ও প্রতারণামুক্ত ব্যবসায়িক মডেল নিশ্চিত করতে এই গাণিতিক সূত্র মেনে চলা হয়। এখানে কোনো ভুয়া বা কাল্পনিক টাকা বণ্টন হয় না; শুধুমাত্র বাস্তব বিক্রয়ের ওপর তৈরি হওয়া মুনাফা স্বয়ংক্রিয়ভাবে লেজারে জমা হয় যা তাৎক্ষণিকভাবে উত্তোলনযোগ্য।',
    'manual_ch_commissions_pool_s1' => 'সাইডবার থেকে "Earnings" সেকশনে প্রবেশ করে আপনার মোট অর্জিত কমিশন এবং উপলব্ধ ব্যালেন্স পর্যালোচনা করুন।',
    'manual_ch_commissions_pool_s2' => 'আর্থিক ব্যালেন্স কার্ডে তিনটি মূল অংশ দেখতে পাবেন: "Available Balance" (উত্তোলনযোগ্য), "Withdrawn" (পরিশোধিত) এবং "Pending" (যাচাইাধীন)।',
    'manual_ch_commissions_pool_s3' => 'তারিখের প্রিসেট ফিল্টার (যেমন: Today, This Week, This Month, All Time) ব্যবহার করে নির্দিষ্ট সময়ের আয় বিশ্লেষণ করুন।',
    'manual_ch_commissions_pool_s4' => 'নিচের বিস্তারিত লেজার টেবিলে প্রতিটি আয়ের লাইন আইটেম লক্ষ্য করুন: তারিখ, কমিশনের ধরন (Direct Referral, Generation, Rank Royalty), হার (%), সোর্স অ্যাকাউন্ট ও অর্ডার আইডি।',
    'manual_ch_commissions_pool_s5' => 'প্রতিটি এন্ট্রির সাথে সংযুক্ত গাণিতিক প্রমাণ ও অর্ডার রেফারেন্স যাচাই করতে "View Transaction Details" এ ক্লিক করুন।',
    'manual_ch_commissions_pool_s6' => 'লেজারের প্রতিটি ক্রেডিট তাৎক্ষণিকভাবে আপনার উপলব্ধ ওয়ালেটে যোগ হয় যা উত্তোলনের জন্য সম্পূর্ণ প্রস্তুত।',
    'manual_ch_commissions_pool_out1' => 'অর্ডার ক্লিয়ারেন্সের মুহূর্তে ডাটাবেসের ডাবল-এন্ট্রি লেজারে ক্রেডিট এন্ট্রি সৃষ্টি হয়।',
    'manual_ch_commissions_pool_out2' => 'ডিলারের পার্সোনাল ওয়ালেটের উপলব্ধ ব্যালেন্স বৃদ্ধি পায় এবং এসএমএস বা ইন-অ্যাপ নোটিফিকেশনের মাধ্যমে অবহিত করা হয়।',
    'manual_ch_commissions_pool_out3' => 'আর্থিক অডিট ট্রেইলে কোনো মিসম্যাচ ছাড়াই কোম্পানির ৬০% এবং পার্টনারের ৪০% ব্যালেন্স সমতা রক্ষা পায়।',
    'manual_ch_commissions_pool_rule1' => 'মোট কমিশন কখনোই কোম্পানির নির্ধারিত ৪০% পুলের বাইরে যেতে পারবে না; এটি সিস্টেম দ্বারা গাণিতিকভাবে সুরক্ষিত।',
    'manual_ch_commissions_pool_rule2' => 'বাতিলকৃত বা রিফান্ড হওয়া অর্ডারের কমিশন স্বয়ংক্রিয়ভাবে রিভার্সাল লেজার এন্ট্রির মাধ্যমে সমন্বয় করা হয়।',
    'manual_ch_commissions_pool_rule3' => 'উত্তোলন করার আগ পর্যন্ত অর্জিত কমিশন আপনার ওয়ালেটে সুরক্ষিত থাকবে; এর কোনো মেয়াদোত্তীর্ণের তারিখ নেই।',
    'manual_ch_commissions_pool_t1' => 'মাসের শেষ দিনে বা সপ্তাহের শুরুতে Earnings স্টেটমেন্ট মিলিয়ে নিন যাতে আপনার হিসাব শতভাগ পরিষ্কার থাকে।',
    'manual_ch_commissions_pool_t2' => 'ডাউনলাইনের বড় অর্ডারের কমিশন আসার পর লেজারের সোর্স অর্ডার নম্বর চেক করে টিমের কোন সদস্য ভালো করছে তা চিহ্নিত করুন।',
    'manual_ch_commissions_pool_warn1' => 'কোম্পানি সক্রিয়করণ (Financial Activation) সম্পন্ন না হওয়া পর্যন্ত ডেমো অ্যাকাউন্টে কোনো আর্থিক পোস্টিং কার্যকর হবে না।',
    'manual_ch_commissions_pool_warn2' => 'লেজারের কোনো তথ্যে অসঙ্গতি মনে হলে তাৎক্ষণিকভাবে লেনদেনের স্ক্রিনশটসহ সাপোর্ট ডেস্কে জানান।',
    'manual_ch_commissions_pool_q1' => '৪০% এবং ৬০% এর হিসাব কীভাবে হয়?',
    'manual_ch_commissions_pool_a1' => 'যেকোনো পণ্যের বিক্রয়মূল্যের ৬০% সরাসরি কোম্পানির কারখানা, কাঁচামাল ও পরিচালন তহবিলে যায় এবং বাকি ৪০% ডিলার ও পার্টনারদের কমিশন পুলে বণ্টিত হয়।',
    'manual_ch_commissions_pool_q2' => 'কমিশন কি সাথে সাথে ওয়ালেটে যোগ হয়?',
    'manual_ch_commissions_pool_a2' => 'হ্যাঁ, ফাইন্যান্স ডেস্ক যখনই কোনো অর্ডারের পেমেন্ট ভেরিফাই করে অনুমোদন দেয়, সাথে সাথে এক সেকেন্ডের মধ্যে কমিশন ওয়ালেটে জমা হয়।',
    // Chapter 8: ranks_royalties
    'manual_ch_ranks_royalties_title' => '৮. ডিলার পদবী স্তর, মাসিক টার্নওভার যোগ্যতা ও গ্লোবাল রয়্যালটি পুল',
    'manual_ch_ranks_royalties_badge' => 'পদোন্নতি ও রয়্যালটি',
    'manual_ch_ranks_royalties_summary' => 'মার্কেটিং অফিসার (MO) থেকে মার্কেটিং এক্সিকিউটিভ (ME) ক্যারিয়ার ল্যাডার, মাসিক পার্সোনাল ও টিম সেলস টার্গেট এবং কোম্পানির মোট টার্নওভার রয়্যালটি শেয়ার।',
    'manual_ch_ranks_royalties_purpose' => 'পদবী ও রয়্যালটি আর্কিটেকচারটি সফল ডিলারদের দীর্ঘমেয়াদী ক্যারিয়ার সুরক্ষা এবং সম্মানজনক স্থায়ী প্যাসিভ আয়ের সুযোগ দেয়। এখানে নির্ধারিত পদবী অর্জনের মাধ্যমে ডিলারগণ কোম্পানির সার্বিক মাসিক বিক্রয়ের একটি নির্দিষ্ট অংশ (Global Royalty) প্রতি মাসে রয়্যালটি বোনাস হিসেবে পান।',
    'manual_ch_ranks_royalties_why' => 'শুধুমাত্র সরাসরি বিক্রির ওপর নির্ভরশীল না থেকে শীর্ষ ডিলারদের কোম্পানির প্রবৃদ্ধির প্রকৃত অংশীদার বানানোই এর মূল লক্ষ্য। এটি দলীয় পারফরম্যান্স ও নেতৃত্বকে মূল্যায়ন করে এবং প্রতি মাসে নিশ্চিত রয়্যালটি প্রদান করে।',
    'manual_ch_ranks_royalties_s1' => 'সাইডবার থেকে "Ranks" সেকশনে প্রবেশ করে আপনার বর্তমান পদবী এবং পরবর্তী পদবীতে পৌঁছানোর অগ্রগতি বার দেখুন।',
    'manual_ch_ranks_royalties_s2' => 'ক্যারিয়ারের মূল পদবীগুলো লক্ষ্য করুন: Marketing Officer (MO), Assistant Manager (AM), Sales Manager (SM) এবং Marketing Executive (ME)।',
    'manual_ch_ranks_royalties_s3' => 'পরবর্তী পদবী অর্জনের জন্য প্রয়োজনীয় ব্যক্তিগত কেনাকাটা (Personal Volume) এবং ডাউনলাইনের সম্মিলিত দলীয় কেনাকাটা (Team Volume) যাচাই করুন।',
    'manual_ch_ranks_royalties_s4' => 'আপনার টিমের সদস্যদের সক্রিয়তা বৃদ্ধি করুন যাতে তাদের সেলস ভলিউম আপনার পদোন্নতির শর্ত পূরণ করে।',
    'manual_ch_ranks_royalties_s5' => 'মাসিক শর্ত পূরণ হলে সিস্টেম স্বয়ংক্রিয়ভাবে আপনাকে নতুন পদবীতে পদোন্নতি প্রদান করবে এবং আপনার প্রোফাইলে নতুন ব্যাজ যুক্ত হবে।',
    'manual_ch_ranks_royalties_s6' => 'প্রতি মাসের ১ তারিখে কোম্পানির মোট টার্নওভারের ওপর নির্ধারিত রয়্যালটি পুল হিসাব করে আপনার ওয়ালেটে রয়্যালটি কমিশন সরাসরি ক্রেডিট করা হবে।',
    'manual_ch_ranks_royalties_out1' => 'ডাটাবেসে ডিলারের Rank স্ট্যাটাস স্বয়ংক্রিয়ভাবে আপগ্রেড হয় এবং সিস্টেমে অফিসিয়াল পদোন্নতি সার্টিফিকেট তৈরি হয়।',
    'manual_ch_ranks_royalties_out2' => 'মাসিক রয়্যালটি পুলে পদবীধারীর অংশগ্রহণের শেয়ার যুক্ত হয়।',
    'manual_ch_ranks_royalties_out3' => 'কোম্পানির লিডারবোর্ড এবং বিশেষ নির্বাহী সভায় বিশেষ সম্মাননা ও স্বীকৃতি প্রদান করা হয়।',
    'manual_ch_ranks_royalties_rule1' => 'রয়্যালটি পাওয়ার জন্য সংশ্লিষ্ট মাসে ডিলারের ন্যূনতম ব্যক্তিগত সক্রিয় কেনাকাটা (Personal Qualification) থাকা বাধ্যতামূলক।',
    'manual_ch_ranks_royalties_rule2' => 'র‍্যাঙ্ক হিসাব করার ক্ষেত্রে শুধুমাত্র অনুমোদিত ও শতভাগ পরিশোধিত অর্ডার গণনা করা হয়; বাকি থাকা অর্ডার হিসেবে আসে না।',
    'manual_ch_ranks_royalties_rule3' => 'টানা নির্দিষ্ট সময় শর্ত পূরণে ব্যর্থ হলে পদবীর গ্রেস পিরিয়ড নিয়ম অনুযায়ী রয়্যালটি স্থগিত হতে পারে।',
    'manual_ch_ranks_royalties_t1' => 'মাসের ২০ তারিখের মধ্যেই আপনার ও আপনার টিমের পয়েন্ট চেক করুন, যাতে শেষ মুহূর্তে টার্গেট পূরণ করতে কোনো ঘাটতি না থাকে।',
    'manual_ch_ranks_royalties_t2' => 'ডাউনলাইনের অন্তত ২-৩ জন লিডারকে পদোন্নতি অর্জনে সহায়তা করুন; এটি আপনার পদবী ধরে রাখাকে সহজ করে।',
    'manual_ch_ranks_royalties_warn1' => 'অন্যায়ভাবে নিজের আইডি দিয়ে ভুয়া কেনাকাটা দেখিয়ে র‍্যাঙ্ক অর্জন করার চেষ্টা করলে সংশ্লিষ্ট পদবী বাতিল করা হবে।',
    'manual_ch_ranks_royalties_warn2' => 'রয়্যালটি পুলের টাকা সম্পূর্ণ কোম্পানির প্রকৃত বিক্রয়ের ওপর নির্ভরশীল; কোনো ফিক্সড কাল্পনিক মুনাফা নয়।',
    'manual_ch_ranks_royalties_q1' => 'আমি কখন পরবর্তী পদবী পাব?',
    'manual_ch_ranks_royalties_a1' => 'আপনার প্রয়োজনীয় পার্সোনাল ও টিম সেলস টার্গেট পূর্ণ হওয়ার সাথে সাথেই সিস্টেম তাৎক্ষণিকভাবে আপনার পদবী আপগ্রেড করে।',
    'manual_ch_ranks_royalties_q2' => 'রয়্যালটি টাকা মাসে কয়বার দেওয়া হয়?',
    'manual_ch_ranks_royalties_a2' => 'রয়্যালটি হিসাব প্রতি মাসের মোট সেলসের ওপর করা হয় এবং প্রতি মাসের শুরুতে একবার সরাসরি ওয়ালেটে ক্রেডিট করা হয়।',
    // Chapter 9: rewards_milestones
    'manual_ch_rewards_milestones_title' => '৯. মাইলফলক অর্জন, স্মার্টফোন, মোটরবাইক ও প্রাইভেট কার রিওয়ার্ড',
    'manual_ch_rewards_milestones_badge' => 'অ্যাসেট রিওয়ার্ড',
    'manual_ch_rewards_milestones_summary' => 'দীর্ঘমেয়াদী সঞ্চয়ী পয়েন্ট মাইলফলক, মোটরবাইক ও এক্সিকিউটিভ কার ইনসেন্টিভ ক্লেইম, ফিজিক্যাল ভেরিফিকেশন এবং বার্ষিক পুরস্কার হস্তান্তর প্রটোকল।',
    'manual_ch_rewards_milestones_purpose' => 'অ্যাসেট রিওয়ার্ড প্রোগ্রামটি শীর্ষস্থানীয় পার্টনারদের অসাধারণ সাফল্যের স্বীকৃতিস্বরূপ বাস্তব সম্পদ (যেমন স্মার্টফোন, ল্যাপটপ, মোটরবাইক এবং প্রিমিয়াম প্রাইভেট কার) উপহার দেওয়ার অফিশিয়াল ব্যবস্থা। এটি দীর্ঘমেয়াদী অর্জনের জন্য তৈরি একটি সম্মানজনক প্রণোদনা।',
    'manual_ch_rewards_milestones_why' => 'নগদ কমিশনের পাশাপাশি ডিলারদের জীবনযাত্রার মান উন্নয়ন এবং তাদের সামাজিকভাবে প্রতিষ্ঠিত করার লক্ষ্যেই কোম্পানি এই অ্যাসেট পুরস্কারসমূহ বরাদ্দ রাখে। এটি পার্টনার ও কোম্পানির মধ্যকার আজীবন অংশীদারিত্বের প্রতীক।',
    'manual_ch_rewards_milestones_s1' => 'সাইডবার মেনু থেকে "Rewards" অথবা "Milestones" সেকশনটি ওপেন করুন।',
    'manual_ch_rewards_milestones_s2' => 'উপলব্ধ রিওয়ার্ড টায়ারগুলো দেখুন: লেভেল ১ (স্মার্ট ডিভাইস/ট্যাবলেট), লেভেল ২ (ল্যাপটপ), লেভেল ৩ (ব্র্যান্ডেড মোটরবাইক) এবং লেভেল ৪ (প্রাইভেট কার)।',
    'manual_ch_rewards_milestones_s3' => 'প্রতিটি রিওয়ার্ডের জন্য প্রয়োজনীয় কিউমুলেটিভ টার্নওভার (Cumulative Milestone Points) এবং আপনার বর্তমান অগ্রগতি পর্যালোচনা করুন।',
    'manual_ch_rewards_milestones_s4' => 'মাইলফলক পয়েন্ট ১০০% সম্পন্ন হলে সংশ্লিষ্ট রিওয়ার্ড কার্ডে "Claim Reward" বাটনটি সক্রিয় হবে।',
    'manual_ch_rewards_milestones_s5' => '"Claim Reward" বাটনে ক্লিক করে আপনার জাতীয় পরিচয়পত্র, ড্রাইভিং লাইসেন্স (প্রযোজ্য ক্ষেত্রে) ও যোগাযোগের তথ্যসহ ক্লেইম সাবমিট করুন।',
    'manual_ch_rewards_milestones_s6' => 'কোম্পানির অডিট বোর্ড আবেদনটি যাচাই করে অনুমোদন দেবে এবং বার্ষিক গ্র্যান্ড গালা অনুষ্ঠানে আনুষ্ঠানিকভাবে চাবি ও দলিল হস্তান্তর করা হবে।',
    'manual_ch_rewards_milestones_out1' => 'রিওয়ার্ড ক্লেইম স্ট্যাটাস "Pending Physical Verification" এ স্থানান্তরিত হয় এবং অডিট বোর্ডে ফাইল নথিভুক্ত হয়।',
    'manual_ch_rewards_milestones_out2' => 'অনুমোদনের পর ডিলারের প্রোফাইলে অফিসিয়াল অ্যাসেট উইনার ব্যাজ যুক্ত হয় এবং প্রেস বিজ্ঞপ্তি প্রকাশ করা হয়।',
    'manual_ch_rewards_milestones_out3' => 'কোম্পানি কর্তৃক গাড়ির রেজিস্ট্রেশন ও আইনি মালিকানা সংক্রান্ত যাবতীয় কাগজপত্র সম্পন্ন করা হয়।',
    'manual_ch_rewards_milestones_rule1' => 'শুধুমাত্র গ্রাহক পর্যায়ে পৌঁছানো এবং শতভাগ পরিশোধিত অর্ডারই মাইলফলক পয়েন্টের জন্য হিসাব করা হবে।',
    'manual_ch_rewards_milestones_rule2' => 'কোনো অবস্থাতেই রিওয়ার্ড পয়েন্ট একজনের অ্যাকাউন্ট থেকে অন্যজনের অ্যাকাউন্টে স্থানান্তর করা যাবে না।',
    'manual_ch_rewards_milestones_rule3' => 'অ্যাসেট রিওয়ার্ড হস্তান্তরের পর নূন্যতম নির্দিষ্ট সময় পর্যন্ত ডিলারশিপ সক্রিয় রাখার সম্মতিপত্রে স্বাক্ষর করতে হয়।',
    'manual_ch_rewards_milestones_t1' => 'রিওয়ার্ড পয়েন্ট কখনও নষ্ট হয় না বা মেয়াদোত্তীর্ণ হয় না; ধৈর্য ধরে দীর্ঘমেয়াদে কাজ করে যান।',
    'manual_ch_rewards_milestones_t2' => 'টিমের অন্যান্য সদস্যদের এই মাইলফলকগুলোর ব্যাপারে উৎসাহিত করুন যাতে তারা সম্মিলিতভাবে দ্রুত এগিয়ে যেতে পারে।',
    'manual_ch_rewards_milestones_warn1' => 'ভুয়া বা সার্কুলার ট্রেডিংয়ের মাধ্যমে পয়েন্ট বাড়ানোর চেষ্টা ধরা পড়লে সমস্ত অর্জিত রিওয়ার্ড পয়েন্ট শূন্য করা হবে।',
    'manual_ch_rewards_milestones_warn2' => 'কোম্পানির অনুমতি ব্যতিরেকে অ্যাসেট রিওয়ার্ড পুরস্কার হিসেবে পাওয়ার পূর্বে কোনো প্রকার অগ্রিম দাবি আইনত গ্রাহ্য নয়।',
    'manual_ch_rewards_milestones_q1' => 'বাইক বা কার রিওয়ার্ড কি নগদে নেওয়া যাবে?',
    'manual_ch_rewards_milestones_a1' => 'কোম্পানি নীতিমালা অনুযায়ী ব্র্যান্ড প্রমোশন ও সুনামের স্বার্থে অ্যাসেট হস্তান্তরই অগ্রাধিকারযোগ্য। বিশেষ ক্ষেত্রে ম্যানেজমেন্টের সাথে কথা বলতে পারেন।',
    'manual_ch_rewards_milestones_q2' => 'রিওয়ার্ড পয়েন্ট কি কমিশন উত্তোলনের সাথে কমে যায়?',
    'manual_ch_rewards_milestones_a2' => 'না! কমিশন উত্তোলন করলেও আপনার লাইফটাইম অর্জিত রিওয়ার্ড পয়েন্ট সম্পূর্ণ অপরিবর্তিত থাকে।',
    // Chapter 10: subdealer_salary_tour
    'manual_ch_subdealer_salary_tour_title' => '১০. সাব-ডিলার মডেল, ক্রয়ের ওপর ৫% মাসিক বেতন ও ২% ট্যুর রিজার্ভ',
    'manual_ch_subdealer_salary_tour_badge' => 'সাব-ডিলার কম্পেনসেশন',
    'manual_ch_subdealer_salary_tour_summary' => 'সাব-ডিলারদের টার্নওভার ভিত্তিক ৫% ফিক্সড বেতন বণ্টন, ২% আন্তর্জাতিক ভ্রমণ ও ট্যুর রিজার্ভ ফান্ড সঞ্চয় এবং স্পনসর ওভাররাইড বেনিফিট।',
    'manual_ch_subdealer_salary_tour_purpose' => 'সাব-ডিলার কম্পেনসেশন মডেলটি তৃণমূল পর্যায়ের আউটলেট ও শপকিপারদের জন্য তৈরি একটি বিশেষ আর্থিক প্যাকেজ। এখানে সাব-ডিলারদের মোট মাসিক পণ্য ক্রয়ের ওপর সরাসরি ৫% হারে মাসিক নিশ্চিত বেতন প্রদান করা হয় এবং অতিরিক্ত ২% অর্থ তাদের ব্যক্তিগত আন্তর্জাতিক ভ্রমণ ফান্ডে স্বয়ংক্রিয়ভাবে সংরক্ষিত হয়।',
    'manual_ch_subdealer_salary_tour_why' => 'ছোট ও মাঝারি উদ্যোক্তাদের নিয়মিত মাসিক আয়ের নিরাপত্তা দিতে এবং তাদের ব্যবসার সাথে দীর্ঘমেয়াদে সম্পৃক্ত রাখতে এই মডেলটি অনন্য। এটি সাব-ডিলারদের প্রতি মাসে ফিক্সড নগদ বেতন ও বাৎসরিক বিদেশ ভ্রমণের সুযোগ করে দেয়।',
    'manual_ch_subdealer_salary_tour_s1' => 'সাব-ডিলার একাউন্ট থেকে সাইডবারে থাকা "Salary" সেকশনে প্রবেশ করুন।',
    'manual_ch_subdealer_salary_tour_s2' => 'বর্তমান চলতি মাসের মোট কোয়ালিফাইং ক্রয় টার্নওভার এবং তার ওপর অর্জিত সম্ভাব্য ৫% বেতন ব্যালেন্স পর্যবেক্ষণ করুন।',
    'manual_ch_subdealer_salary_tour_s3' => '"Tour Reserve" কার্ডে আপনার সঞ্চিত ২% ভ্রমণ ফান্ডের মোট জমা টাকা এবং পরবর্তী গ্লোবাল ট্যুরের গন্তব্য দেখুন।',
    'manual_ch_subdealer_salary_tour_s4' => 'বেতন সচল রাখতে চলতি মাসের ন্যূনতম নির্ধারিত ক্রয় কোটা (যেমন BDT 10,000 বা পলিসি নির্ধারিত পরিমাণ) সম্পন্ন করুন।',
    'manual_ch_subdealer_salary_tour_s5' => 'মাস শেষ হলে কোম্পানির ফাইন্যান্স ডেস্ক হিসাব ক্লোজ করে ৫% বেতনের টাকা সরাসরি আপনার উপলব্ধ "Earnings Wallet" এ পাঠিয়ে দেবে।',
    'manual_ch_subdealer_salary_tour_s6' => 'জমা হওয়া বেতনের টাকা আপনি সাধারণ কমিশনের মতোই তাৎক্ষণিকভাবে ব্যাংক বা মোবাইল ব্যাংকিংয়ের (bKash/Nagad) মাধ্যমে উত্তোলন করতে পারবেন।',
    'manual_ch_subdealer_salary_tour_out1' => 'মাসের শুরুতে বেতনের ক্রেডিট এন্ট্রি তৈরি হয় এবং ওয়ালেট ব্যালেন্স স্বয়ংক্রিয়ভাবে বৃদ্ধি পায়।',
    'manual_ch_subdealer_salary_tour_out2' => 'ট্যুর রিজার্ভ লেজারে ২% অর্থ যোগ হয়ে আপনার আন্তর্জাতিক ভ্রমণের টিকিট ও ভিসার ফান্ড সমৃদ্ধ হয়।',
    'manual_ch_subdealer_salary_tour_out3' => 'সাব-ডিলারের স্পনসর ডিলার তার অ্যাকাউন্টে সংশ্লিষ্ট ওভাররাইড বোনাস লাভ করেন।',
    'manual_ch_subdealer_salary_tour_rule1' => 'বেতন পাওয়ার জন্য সংশ্লিষ্ট মাসে ন্যূনতম নির্ধারিত ক্রয় ভলিউম সম্পন্ন করা বাধ্যতামূলক।',
    'manual_ch_subdealer_salary_tour_rule2' => 'ট্যুর রিজার্ভ ফান্ডের টাকা শুধুমাত্র অফিসিয়াল ভ্রমণ ইভেন্টের জন্য প্রযোজ্য; এটি সরাসরি নগদে উত্তোলনযোগ্য নয়।',
    'manual_ch_subdealer_salary_tour_rule3' => 'সাব-ডিলার পরবর্তীতে পূর্ণাঙ্গ ডিলারশিপে আপগ্রেড করলে তার ট্যুর ফান্ড স্বয়ংক্রিয়ভাবে নতুন অ্যাকাউন্টে স্থানান্তরিত হবে।',
    'manual_ch_subdealer_salary_tour_t1' => 'মাসের শেষ সপ্তাহের জন্য অপেক্ষা না করে প্রতি সপ্তাহে ছোট ছোট অর্ডারের মাধ্যমে লক্ষ্যমাত্রা পূরণ করে ফেলুন।',
    'manual_ch_subdealer_salary_tour_t2' => 'আপনার আশেপাশের অন্যান্য দোকানদারদের সাব-ডিলার হিসেবে যুক্ত হতে উৎসাহিত করুন।',
    'manual_ch_subdealer_salary_tour_warn1' => 'রিটার্ন বা বাতিল হওয়া অর্ডারের ক্ষেত্রে সংশ্লিষ্ট বেতনের হিসাব আনুপাতিক হারে কর্তন করা হবে।',
    'manual_ch_subdealer_salary_tour_warn2' => 'ভুয়া ক্রয়াদেশ দিয়ে বেতন দাবি করা শৃঙ্খলাভঙ্গের শামিল এবং তদন্তসাপেক্ষে আইডি স্থগিত হতে পারে।',
    'manual_ch_subdealer_salary_tour_q1' => 'আমি কি বেতনের টাকা বিকাশ বা ব্যাংকে তুলতে পারব?',
    'manual_ch_subdealer_salary_tour_a1' => 'হ্যাঁ! মাসের শুরুতে বেতন ওয়ালেটে ক্রেডিট হওয়ার পর আপনি বিকাশ, নগদ, রকেট বা যেকোনো ব্যাংক অ্যাকাউন্টে তা তুলতে পারবেন।',
    'manual_ch_subdealer_salary_tour_q2' => 'ট্যুর রিজার্ভের টাকা দিয়ে কোথায় যাওয়া হয়?',
    'manual_ch_subdealer_salary_tour_a2' => 'কোম্পানি বার্ষিক ভিত্তিতে ব্যাংকক, মালয়েশিয়া, দুবাই বা তুরস্ক ভ্রমণের আয়োজন করে। আপনার জমার পরিমাণের ভিত্তিতে ট্যুর প্যাকেজ নির্ধারণ করা হয়।',
    // Chapter 11: withdrawals
    'manual_ch_withdrawals_title' => '১১. পার্টনার ওয়ালেট, উত্তোলন অনুরোধ ও পেআউট নিষ্পত্তি প্রক্রিয়া',
    'manual_ch_withdrawals_badge' => 'ওয়ালেট ও পেআউট',
    'manual_ch_withdrawals_summary' => 'উপলব্ধ ব্যালেন্স বনাম পেন্ডিং হিসাব, সর্বনিম্ন ৫০০ টাকা উত্তোলনের নিয়ম, ব্যাংক ও এমএফএস (bKash/Nagad/Rocket) সেটেলমেন্ট এবং রসিদ যাচাই।',
    'manual_ch_withdrawals_purpose' => 'উত্তোলন ও পেআউট মডিউলটি পার্টনারদের অর্জিত আয় নিরাপদে তাদের নিজস্ব ব্যক্তিগত ব্যাংক বা মোবাইল ব্যাংকিং একাউন্টে স্থানান্তর করার অফিশিয়াল মাধ্যম। এখানে স্বয়ংক্রিয় লেজার যাচাই, অনুমোদন পাইপলাইন এবং ডিজিটাল পেমেন্ট রসিদ সংযুক্তির ব্যবস্থা রয়েছে।',
    'manual_ch_withdrawals_why' => 'পার্টনারদের পরিশ্রমের ন্যায্য উপার্জন দ্রুত ও নির্ভুলভাবে পৌঁছে দেওয়াই এই সিস্টেমের সর্বোচ্চ অগ্রাধিকার। এতে কোনো অদৃশ্য চার্জ নেই এবং প্রতিটি লেনদেনের অফিসিয়াল ডিজিটাল রসিদ পিডিএফ আকারে ডাউনলোড করা যায়।',
    'manual_ch_withdrawals_s1' => 'সাইডবার থেকে "Withdrawals" সেকশনে প্রবেশ করুন।',
    'manual_ch_withdrawals_s2' => 'আপনার বর্তমান উপলব্ধ ব্যালেন্স (Available Balance) চেক করুন; এটি অবশ্যই সর্বনিম্ন ৫০০ টাকা (BDT 500) বা তার বেশি হতে হবে।',
    'manual_ch_withdrawals_s3' => '"Request Withdrawal" বাটনে ক্লিক করে উত্তোলনের ফর্মটি ওপেন করুন।',
    'manual_ch_withdrawals_s4' => 'টাকার পরিমাণ (Amount) প্রবেশ করান এবং আপনার পছন্দের পেমেন্ট মাধ্যম (Bank Transfer, bKash, Nagad, Rocket) নির্বাচন করুন।',
    'manual_ch_withdrawals_s5' => 'নির্বাচিত মাধ্যমের প্রয়োজনীয় তথ্য (যেমন: ব্যাংকের নাম, ব্রাঞ্চ, অ্যাকাউন্ট নম্বর, রাউটিং নম্বর অথবা মোবাইল ব্যাংকিং নম্বর) দিন।',
    'manual_ch_withdrawals_s6' => '"Submit Request" এ ক্লিক করুন; সিস্টেম তাৎক্ষণিকভাবে আপনার অনুরোধটি পেন্ডিং পেআউট কিউতে নথিভুক্ত করবে।',
    'manual_ch_withdrawals_s7' => 'কোম্পানির ফাইন্যান্স ডেস্ক অনুরোধটি যাচাই করে টাকা পাঠানোর পর সংশ্লিষ্ট ট্রানজেকশন আইডি (TrxID) ও পেমেন্ট স্লিপ আপলোড করবে।',
    'manual_ch_withdrawals_s8' => 'উত্তোলন সফল হলে স্ট্যাটাস "Paid" হবে এবং আপনি "Download Official Payment Receipt" বাটনে ক্লিক করে রসিদ সংরক্ষণ করতে পারবেন।',
    'manual_ch_withdrawals_out1' => 'অনুরোধ জমা দেওয়ার সাথে সাথে ওয়ালেটের উপলব্ধ ব্যালেন্স থেকে সমপরিমাণ অর্থ "Pending Withdrawal" এ লক হয়, যাতে অতিরিক্ত উত্তোলন না ঘটে।',
    'manual_ch_withdrawals_out2' => 'ফাইন্যান্স ডেস্কে রিয়েল-টাইম নোটিফিকেশন যায় এবং পেমেন্ট সম্পন্ন হলে ডিলারের ফোনে এসএমএস নোটিফিকেশন পৌঁছায়।',
    'manual_ch_withdrawals_out3' => 'লেজারে ডেবিট এন্ট্রি বসে এবং ডিলারের ব্যাংক/মোবাইল অ্যাকাউন্টে টাকা সফলভাবে জমা হয়।',
    'manual_ch_withdrawals_rule1' => 'সর্বনিম্ন উত্তোলন সীমা ৫০০ টাকা; এর কম ব্যালেন্সের জন্য অনুরোধ সাবমিট করা যাবে না।',
    'manual_ch_withdrawals_rule2' => 'সরকারি কর আইন অনুযায়ী প্রযোজ্য ক্ষেত্রে উৎসে কর কর্তন (TDS) নীতিমালা অনুসরণ করা হতে পারে যা রসিদে স্পষ্ট থাকবে।',
    'manual_ch_withdrawals_rule3' => 'অ্যাকাউন্টে কোনো অমীমাংসিত বকেয়া (Dues) থাকলে তা নিষ্পত্তি না করা পর্যন্ত পেআউট স্থগিত থাকবে।',
    'manual_ch_withdrawals_t1' => 'সপ্তাহের কাজের দিনে (রবিবার থেকে বৃহস্পতিবার) ব্যাংক চলাকালীন সময়ে উত্তোলনের অনুরোধ পাঠালে দ্রুত পেমেন্ট সম্পন্ন হয়।',
    'manual_ch_withdrawals_t2' => 'মোবাইল ব্যাংকিং ব্যবহারের ক্ষেত্রে পার্সোনাল নম্বর সঠিকভাবে টাইপ করেছেন কিনা দুইবার চেক করুন।',
    'manual_ch_withdrawals_warn1' => 'ভুল ব্যাংক অ্যাকাউন্ট নম্বর বা অন্যের বিকাশ নম্বর দিলে টাকা ভুল অ্যাকাউন্টে যাওয়ার ঝুঁকি থাকে যার জন্য কোম্পানি দায়ী হবে না।',
    'manual_ch_withdrawals_warn2' => 'সন্দেহজনক অ্যাকাউন্টে পেআউট প্রসেস করার পূর্বে কোম্পানি অতিরিক্ত এনআইডি ভেরিফিকেশন চাইতে পারে।',
    'manual_ch_withdrawals_q1' => 'টাকা পেতে কতক্ষণ সময় লাগে?',
    'manual_ch_withdrawals_a1' => 'বিকাশ ও নগদে সাধারণত ১২ থেকে ২৪ ঘণ্টার মধ্যে এবং ব্যাংক ট্রান্সফারে ১-২ কার্যদিবসের মধ্যে টাকা পৌঁছে যায়।',
    'manual_ch_withdrawals_q2' => 'আমার উত্তোলন অনুরোধ কি বাতিল হতে পারে?',
    'manual_ch_withdrawals_a2' => 'যদি অ্যাকাউন্টের তথ্যে কোনো ভুল থাকে বা বকেয়া সমন্বয় বাকি থাকে, তবে ফাইন্যান্স টিম কারণ উল্লেখ করে অনুরোধটি রিজেক্ট করতে পারে এবং টাকা পুনরায় ওয়ালেটে ফেরত আসে।',
    // Chapter 12: reports
    'manual_ch_reports_title' => '১২. পূর্ণাঙ্গ ব্যবসায়িক বিবরণী, আর্থিক অডিট ট্রেইল ও ডাউনলোডযোগ্য রিপোর্ট',
    'manual_ch_reports_badge' => 'অডিট ও অ্যানালিটিক্স',
    'manual_ch_reports_summary' => 'তারিখভিত্তিক প্রিসেট ও কাস্টম ফিল্টার, কমিশন ব্রেকডাউন, কেনাকাটার হিস্ট্রি, ডেবিট-ক্রেডিট লেজার স্টেটমেন্ট এবং অফিসিয়াল অডিট পিডিএফ ডাউনলোড।',
    'manual_ch_reports_purpose' => 'রিপোর্ট ও স্টেটমেন্ট মডিউলটি যেকোনো পার্টনারের সমগ্র ব্যবসায়িক লেনদেনের পূর্ণাঙ্গ আর্থিক অডিট বিবরণী। এটি শুরু থেকে শেষ পর্যন্ত কত টাকার পণ্য কেনা হয়েছে, কত টাকা কমিশন এসেছে, কত টাকা উত্তোলন হয়েছে এবং বর্তমানে কত পাওনা আছে—সবকিছুর একটি অকাট্য গাণিতিক ব্যালেন্স শিট প্রদান করে।',
    'manual_ch_reports_why' => 'ব্যক্তিগত ব্যবসা পরিচালনা, কর ফাইলিং এবং কোম্পানির সাথে নিখুঁত আর্থিক স্বচ্ছতা বজায় রাখার জন্য প্রতিটি লেনদেনের আনুষ্ঠানিক লিখিত রেকর্ড থাকা আবশ্যক। এটি পার্টনারদের নিজেদের ব্যবসা কতটুকু লাভজনক তা স্পষ্ট বুঝতে সাহায্য করে।',
    'manual_ch_reports_s1' => 'সাইডবার মেনু থেকে "Full Report" অথবা "Reports" সেকশনে ক্লিক করুন।',
    'manual_ch_reports_s2' => 'শীর্ষে থাকা তারিখ ফিল্টার প্রিসেট ব্যবহার করুন: Today (আজ), This Month (চলতি মাস), Last Month (গত মাস) অথবা কাস্টম তারিখ (From - To) নির্ধারণ করুন।',
    'manual_ch_reports_s3' => '"Apply Filters" এ ক্লিক করলে নির্বাচিত সময়ের সমস্ত হিসাব স্ক্রিনে প্রদর্শিত হবে।',
    'manual_ch_reports_s4' => 'সামারি কার্ডগুলোতে মোট কেনাকাটা (Total Orders), মোট কমিশন (Total Commission), মোট উত্তোলন (Total Payouts) এবং সমাপনী ব্যালেন্স (Closing Balance) দেখুন।',
    'manual_ch_reports_s5' => 'নিচে নেমে "Team Performance" সেকশনে আপনার ডাউনলাইনের কে কত ভলিউমের ব্যবসা করেছে তার তালিকা পর্যালোচনা করুন।',
    'manual_ch_reports_s6' => 'অফিসিয়াল প্রিন্ট বা আইনি নথিপত্রের জন্য "Download Full Report PDF" বাটনে ক্লিক করে উচ্চমানের ফরম্যাটেড পিডিএফ সংরক্ষণ করুন।',
    'manual_ch_reports_out1' => 'সিস্টেম রিয়েল-টাইমে ডাটাবেসের সমস্ত জার্নাল এন্ট্রি স্ক্যান করে একটি স্বয়ংসম্পূর্ণ অডিট ব্যালেন্স শিট রেন্ডার করে।',
    'manual_ch_reports_out2' => 'পিডিএফ জেনারেটরে কোম্পানির অফিশিয়াল সিল ও কিউআর ভেরিফিকেশনসহ প্রিন্ট-রেডি ডকুমেন্ট প্রস্তুত হয়।',
    'manual_ch_reports_out3' => 'ব্যবসায়িক সিদ্ধান্ত গ্রহণে পার্টনারদের সেলস ট্রেন্ড এবং সবচেয়ে বেশি বিক্রিত পণ্যের তথ্য স্পষ্ট হয়।',
    'manual_ch_reports_rule1' => 'রিপোর্টে প্রদর্শিত সমস্ত তথ্য মূল ডাটাবেসের অপরিবর্তনীয় অডিট লগ থেকে সংগৃহীত হয়; কোনো তথ্য ম্যানুয়ালি এডিট করা সম্ভব নয়।',
    'manual_ch_reports_rule2' => 'নির্বাচিত তারিখে কোনো লেনদেন না থাকলে চার্ট খালি দেখাবে; এটি কোনো ত্রুটি নয়।',
    'manual_ch_reports_rule3' => 'রিপোর্টের সমাপনী ব্যালেন্স সবসময় আপনার ওয়ালেটের বর্তমান ব্যালেন্সের সাথে হুবহু মিলে যাবে।',
    'manual_ch_reports_t1' => 'প্রতি মাসের ১ তারিখে পূর্ববর্তী মাসের সম্পূর্ণ রিপোর্টটি পিডিএফ হিসেবে ডাউনলোড করে আপনার ব্যক্তিগত ফাইলে সংরক্ষণ করুন।',
    'manual_ch_reports_t2' => 'কাস্টম রেঞ্জ ব্যবহার করে কোনো নির্দিষ্ট উৎসবের (যেমন ঈদ ক্যাম্পেইন) বিক্রির পরিমাণ ও লাভ আলাদা করে বিশ্লেষণ করুন।',
    'manual_ch_reports_warn1' => 'অফিসিয়াল রিপোর্ট পিডিএফে কোনো রূপ কাটছাঁট বা পরিবর্তন করা আইনত দণ্ডনীয়।',
    'manual_ch_reports_warn2' => 'অনেক বড় রেঞ্জ (যেমন কয়েক বছর) নির্বাচন করলে ব্রাউজারে রিপোর্ট লোড হতে কয়েক সেকেন্ড অতিরিক্ত সময় লাগতে পারে।',
    'manual_ch_reports_q1' => 'রিপোর্টের ব্যালেন্স আর ওয়ালেটের ব্যালেন্সের মধ্যে কি পার্থক্য হতে পারে?',
    'manual_ch_reports_a1' => 'না, কখনোই নয়। রিপোর্ট ও ওয়ালেট একই সেন্ট্রাল ডাটাবেস লেজার থেকে আসে, তাই একটি পয়সারও গরমিল হওয়া অসম্ভব।',
    'manual_ch_reports_q2' => 'আমি কি আমার ইনকাম ট্যাক্স রিটার্নে এই পিডিএফ ব্যবহার করতে পারব?',
    'manual_ch_reports_a2' => 'হ্যাঁ, এটি একটি অফিসিয়াল এবং অডিট-যোগ্য ব্যবসায়িক স্টেটমেন্ট যা বৈধ ব্যবসায়িক আয় ও খরচের হিসাব হিসেবে গ্রহণযোগ্য।',
    // Chapter 13: treasury_capital_flow
    'manual_ch_treasury_capital_flow_title' => '১৩. কোম্পানি ট্রেজারি, মূলধন প্রবাহ ও ব্যাংক হিসাব ব্যবস্থাপনা',
    'manual_ch_treasury_capital_flow_badge' => 'ট্রেজারি ও মূলধন',
    'manual_ch_treasury_capital_flow_summary' => 'কোম্পানির মোট ক্যাশ ইনফ্লোর ৬০% পরিচালন মূলধন নিয়ন্ত্রণ, ব্যাংক ও মার্চেন্ট এমএফএস কালেকশন হিসাব, দৈনিক ক্যাশ ফ্লো রিকনসিলিয়েশন ও তারল্য রিজার্ভ।',
    'manual_ch_treasury_capital_flow_purpose' => 'ট্রেজারি ও ক্যাপিটাল ফ্লো মডিউলটি কোম্পানির শীর্ষ ফাইন্যান্স টিম ও মালিকানার জন্য প্রস্তুতকৃত সর্বোচ্চ আর্থিক নিয়ন্ত্রণ কেন্দ্র। এখানে প্রতিটি টাকা কালেকশন থেকে শুরু করে ৬০% কোম্পানি পরিচালন মূলধন এবং ৪০% পার্টনার কমিশন পুলে বিভক্ত হওয়ার সামগ্রিক প্রবাহ পর্যবেক্ষণ ও ব্যালেন্স শিট সমন্বয় করা হয়।',
    'manual_ch_treasury_capital_flow_why' => 'প্রতিষ্ঠানের দীর্ঘমেয়াদী আর্থিক সক্ষমতা, কাঁচামাল সংগ্রহের তারল্য এবং ব্যাংকিং স্থিতি নিশ্চিত করতে এই ট্রেজারি নিয়ন্ত্রণ অপরিহার্য। এটি কোম্পানির সমস্ত ব্যাংক হিসাব ও এমএফএস মার্চেন্ট অ্যাকাউন্টের রিয়েল-টাইম হিসাব পরিষ্কার রাখে।',
    'manual_ch_treasury_capital_flow_s1' => 'ম্যানেজমেন্ট বা অ্যাডমিন অ্যাকাউন্ট থেকে সাইডবারের "Finance Ops" গ্রুপের অধীনে "Treasury" সেকশনে প্রবেশ করুন।',
    'manual_ch_treasury_capital_flow_s2' => 'কোম্পানির মোট ক্যাশ ইনফ্লো (Gross Cash Inflow), ৬০% কোম্পানি রিটেইন্ড ফান্ড এবং ৪০% পার্টনার কমিশন ফান্ডের রিয়েল-টাইম পাই-চার্ট ও অনুপাত দেখুন।',
    'manual_ch_treasury_capital_flow_s3' => 'সক্রিয় পেমেন্ট অ্যাকাউন্টস ট্যাবে ক্লিক করে কোম্পানির ব্যাংক একাউন্ট (যেমন: City Bank, Dutch Bangla, Islami Bank) এবং মার্চেন্ট বিকাশ/নগদ ব্যালেন্স পর্যালোচনা করুন।',
    'manual_ch_treasury_capital_flow_s4' => 'প্রতিদিনের কালেকশন স্টেটমেন্ট স্ক্যান করে দেখুন কোন অ্যাকাউন্ট মারফত কত টাকা জমা হয়েছে।',
    'manual_ch_treasury_capital_flow_s5' => 'পরিচালন ব্যয় ও সাপ্লায়ার পেমেন্টের জন্য ট্রেজারি থেকে প্রয়োজনীয় তহবিল বরাদ্দ ও অনুমোদনের ব্যবস্থা করুন।',
    'manual_ch_treasury_capital_flow_s6' => 'ট্রেজারি লেজারের সাথে রিয়েল-টাইম ব্যাংক স্টেটমেন্টের রিকনসিলিয়েশন মিলিয়ে "Reconcile Balances" নিশ্চিত করুন।',
    'manual_ch_treasury_capital_flow_out1' => 'প্রতিটি ইনকামিং অর্ডারের পেমেন্ট অনুমোদনের সাথে সাথে ট্রেজারি ব্যালেন্স ৬০/৪০ অনুপাতে তাৎক্ষণিকভাবে সমন্বয় হয়।',
    'manual_ch_treasury_capital_flow_out2' => 'কোম্পানির নির্বাহী আর্থিক বিবরণীতে কোনো প্রকার গরমিল ছাড়া শতভাগ মিল সংরক্ষিত থাকে।',
    'manual_ch_treasury_capital_flow_out3' => 'আর্থিক ঝুঁকি ও তারল্য সংকটের পূর্বাভাস পেয়ে প্রশাসন কার্যকর সিদ্ধান্ত গ্রহণ করতে পারে।',
    'manual_ch_treasury_capital_flow_rule1' => 'ট্রেজারি ড্যাশবোর্ডটি অত্যন্ত সংবেদনশীল এবং শুধুমাত্র অনুমোদিত ফাইন্যান্স ডিরেক্টর ও ওনারদের জন্য প্রবেশযোগ্য।',
    'manual_ch_treasury_capital_flow_rule2' => 'ট্রেজারি অ্যাকাউন্ট থেকে যেকোনো মূলধন উত্তোলনের জন্য ডুয়াল-অথরাইজেশন (মালিকানা সম্মতি) আবশ্যক।',
    'manual_ch_treasury_capital_flow_rule3' => 'দৈনিক কালেকশনের হিসাব প্রতি কর্মদিবসের শেষে অবশ্যই ক্লোজিং ভেরিফিকেশন সম্পন্ন করতে হবে।',
    'manual_ch_treasury_capital_flow_t1' => 'মার্চেন্ট বিকাশ ও নগদের দৈনিক ক্যাশ-ইন লিমিট নিয়মিত পর্যবেক্ষণ করুন যাতে ডিলারদের পেমেন্ট ক্লেইম আটকে না যায়।',
    'manual_ch_treasury_capital_flow_t2' => 'ব্যাংক ছুটির দিনের আগে পর্যাপ্ত তারল্য রিজার্ভ নিশ্চিত করুন যাতে জরুরি পেআউট বা সাপ্লাই চেইন সচল থাকে।',
    'manual_ch_treasury_capital_flow_warn1' => 'অননুমোদিত কোনো কর্মকর্তা ট্রেজারি ডাটা দেখতে বা পরিবর্তন করতে পারবে না; যেকোনো অবৈধ প্রচেষ্টা সিস্টেমে সতর্কবার্তা পাঠায়।',
    'manual_ch_treasury_capital_flow_warn2' => 'ব্যাংক রিকনসিলিয়েশনে কোনো অমিল দেখা দিলে তাৎক্ষণিকভাবে অডিট স্থগিত করে অনুসন্ধান করুন।',
    'manual_ch_treasury_capital_flow_q1' => 'ট্রেজারির ৬০% ফান্ড কী কাজে ব্যবহৃত হয়?',
    'manual_ch_treasury_capital_flow_a1' => 'এটি পণ্যের উৎপাদন, কাঁচামাল আমদানি, ওয়্যারহাউস পরিচালনা, কর্মচারীদের বেতন এবং প্রতিষ্ঠানের সম্প্রসারণ মূলধন হিসেবে সংরক্ষিত থাকে।',
    'manual_ch_treasury_capital_flow_q2' => 'ট্রেজারি থেকে কি সরাসরি পেআউট দেওয়া হয়?',
    'manual_ch_treasury_capital_flow_a2' => 'না, পেআউটের জন্য আলাদা ক্লিয়ারিং অ্যাকাউন্ট ব্যবহৃত হয়, যা ট্রেজারির মূল ফান্ড থেকে পৃথক থাকে।',
    // Chapter 14: owner_benefits_fund
    'manual_ch_owner_benefits_fund_title' => '১৪. মালিকানা বেনিফিট ফান্ড, কনফিডেনশিয়াল ইকুইটি ও মূলধন সুরক্ষা',
    'manual_ch_owner_benefits_fund_badge' => 'মালিকানা ইকুইটি',
    'manual_ch_owner_benefits_fund_summary' => 'কোম্পানি মালিকানার জন্য কঠোরভাবে সংরক্ষিত প্রফিট রিজার্ভ, ডিস্ট্রিবিউটর কমিশনের পর অবশিষ্ট নেট ইকুইটি শেয়ার এবং গোপনীয় অডিট পৃথকীকরণ।',
    'manual_ch_owner_benefits_fund_purpose' => 'ওনার বেনিফিটস রিজার্ভ ফান্ড হলো সর্বোচ্চ মালিকানা কর্তৃপক্ষের জন্য তৈরি একচেটিয়া গোপনীয় ও সুরক্ষিত ফান্ড লেজার। নেট মুনাফা ও পরিচালন উদ্বৃত্ত থেকে মালিকানার প্রাপ্য ইকুইটি শেয়ার স্বচ্ছ ও নিখুঁতভাবে এই ফান্ডে সংরক্ষিত হয়, যা সাধারণ স্টাফ ও ডিলারদের প্রবেশাধিকারের বাইরে থাকে।',
    'manual_ch_owner_benefits_fund_why' => 'প্রতিষ্ঠাতার বিনিয়োগ নিরাপত্তা, কোম্পানির নিট সম্পদ বৃদ্ধি এবং ভবিষ্যৎ মেগা-প্রকল্প বাস্তবায়নের জন্য মালিকানা রিজার্ভের পৃথকীকরণ অত্যন্ত জরুরি। এটি প্রাতিষ্ঠানিক আর্থিক সুরক্ষার সর্বোচ্চ স্তর নিশ্চিত করে।',
    'manual_ch_owner_benefits_fund_s1' => 'শুধুমাত্র সুপার অ্যাডমিন / ওনার অ্যাকাউন্টে লগইন করে সাইডবার থেকে "Benefits Fund" সেকশনটি খুলুন।',
    'manual_ch_owner_benefits_fund_s2' => 'ফান্ডের বর্তমান মোট পুঞ্জীভূত ব্যালেন্স এবং চলতি অর্থবছরের নেট ইকুইটি গ্রোথ পর্যবেক্ষণ করুন।',
    'manual_ch_owner_benefits_fund_s3' => 'প্রতিটি অর্ডারের ওপর ভিত্তি করে লাইন-বাই-লাইন ওনার ইকুইটি ক্রেডিট এন্ট্রি পর্যালোচনা করুন: অর্ডার আইডি, ক্রেতার তথ্য, মোট ইনভয়েস মূল্য এবং ওনার ফান্ডের নেট শেয়ার।',
    'manual_ch_owner_benefits_fund_s4' => 'ফান্ডের অর্থ পুনঃবিনিয়োগ (Reinvestment) অথবা মালিকানা লভ্যাংশ হিসেবে উত্তোলনের জন্য অনুমোদন দিন।',
    'manual_ch_owner_benefits_fund_s5' => 'অডিট হিস্ট্রি স্ক্যান করে নিশ্চিত করুন যে সমস্ত ডিস্ট্রিবিউশন শেষে কোনো উদ্বৃত্ত হারিয়ে যায়নি।',
    'manual_ch_owner_benefits_fund_s6' => 'বাৎসরিক ট্যাক্স অডিট ও আর্থিক প্রতিবেদন পর্যালোচনার জন্য গোপনীয় ইকুইটি স্টেটমেন্ট ডাউনলোড করুন।',
    'manual_ch_owner_benefits_fund_out1' => 'প্রতিটি সফল অর্ডারের পর নিট মুনাফার মালিকানা অংশ স্বয়ংক্রিয়ভাবে ওনার ফান্ড লেজারে জমা হয়।',
    'manual_ch_owner_benefits_fund_out2' => 'কোম্পানির প্রাতিষ্ঠানিক নিট মূল্য (Net Worth) রিয়েল-টাইমে বৃদ্ধি পায় এবং সংরক্ষিত থাকে।',
    'manual_ch_owner_benefits_fund_out3' => 'এই ফান্ডের কোনো তথ্য বা পরিসংখ্যান কোনো ডিলার, সাব-ডিলার বা সাধারণ কর্মচারীর ইন্টারফেসে দৃশ্যমান হয় না।',
    'manual_ch_owner_benefits_fund_rule1' => 'এই মডিউলে শুধুমাত্র প্ল্যাটফর্মের অনুমোদিত মালিক (Owner Role) এককভাবে প্রবেশ করতে পারবেন; কর্মচারীদের কোনো ক্ষমতা নেই।',
    'manual_ch_owner_benefits_fund_rule2' => 'ফান্ডের প্রতিটি এন্ট্রি ক্রিপ্টোগ্রাফিক হ্যাশ দ্বারা সুরক্ষিত এবং কোনো অবস্থাতেই অতীতের কোনো এন্ট্রি মুছে ফেলা যাবে না।',
    'manual_ch_owner_benefits_fund_rule3' => 'পার্টনারদের সমস্ত বৈধ কমিশন ও ভেন্ডর দায় পরিশোধের পরই কেবল নেট ইকুইটি হিসাব সম্পন্ন হয়।',
    'manual_ch_owner_benefits_fund_t1' => 'প্রতিমাসের শেষে ওনার ফান্ডের গ্রোথ পর্যালোচনা করে ভবিষ্যৎ কাঁচামাল আমদানি ও ফ্যাক্টরি সম্প্রসারণের পরিকল্পনা তৈরি করুন।',
    'manual_ch_owner_benefits_fund_t2' => 'আপনার মালিকানা অ্যাকাউন্টের জন্য জটিল পাসওয়ার্ড এবং টু-ফ্যাক্টর অথেন্টিকেশন (2FA) চালু রাখুন।',
    'manual_ch_owner_benefits_fund_warn1' => 'এই ফান্ডের তথ্য সম্পূর্ণ গোপনীয়; কোনো স্ক্রিনশট বা হিসাব অননুমোদিত কারো কাছে প্রকাশ করা কোম্পানি স্বার্থবিরোধী।',
    'manual_ch_owner_benefits_fund_warn2' => 'মালিকানা অ্যাকাউন্ট অন্য কারো সাথে শেয়ার করবেন না।',
    'manual_ch_owner_benefits_fund_q1' => 'স্টাফ বা ম্যানেজাররা কি ওনার ফান্ড দেখতে পারে?',
    'manual_ch_owner_benefits_fund_a1' => 'না! কর্মচারীদের পোর্টালে এই সেকশনটি সম্পূর্ণ অনুপস্থিত এবং সার্ভার সাইড থেকে এটি পুরোপুরি ব্লক করা থাকে।',
    'manual_ch_owner_benefits_fund_q2' => 'ওনার ফান্ডের টাকা কি পার্টনার কমিশনের সাথে জড়িত?',
    'manual_ch_owner_benefits_fund_a2' => 'না, পার্টনারদের ৪০% কমিশন সম্পূর্ণ আলাদাভাবে পরিশোধ করা হয়। ওনার ফান্ড কোম্পানির ৬০% রিটেইন্ড শেয়ারের অভ্যন্তরীণ উদ্বৃত্ত থেকে আসে।',
    // Chapter 15: staff_ops
    'manual_ch_staff_ops_title' => '১৫. স্টাফ অপারেশন, পারমিশন ম্যাট্রিক্স ও ডুয়াল ড্যাশবোর্ড সুইচিং',
    'manual_ch_staff_ops_badge' => 'স্টাফ গভর্নেন্স',
    'manual_ch_staff_ops_summary' => 'অ্যাকাউন্টস, ডিসপ্যাচ, ইনভেন্টরি ও সাপোর্ট স্টাফদের সুনির্দিষ্ট ক্ষমতা প্রদান, পেআউট অনুমোদন, অর্ডার প্রসেসিং এবং পার্টনার-স্টাফ ডুয়াল ড্যাশবোর্ড সুবিধা।',
    'manual_ch_staff_ops_purpose' => 'স্টাফ অপারেশন মডিউলটি কোম্পানির দৈনন্দিন প্রাতিষ্ঠানিক কার্যক্রম (অর্ডার প্যাকেজিং, পেমেন্ট ক্লেইম ভেরিফিকেশন, উত্তোলন অনুমোদন এবং সাপোর্ট টিকেট ম্যানেজমেন্ট) পরিচালনার জন্য নিয়োজিত কর্মচারীদের ওয়ার্কস্পেস। এটি দায়িত্ব পৃথকীকরণ (Separation of Duties) নীতিতে পরিচালিত হয়।',
    'manual_ch_staff_ops_why' => 'একটি বৃহৎ ব্যবসায়িক প্রতিষ্ঠানে ভুল বা জালিয়াতি রোধ করতে প্রতিটি কর্মচারীকে শুধুমাত্র তার কাজের সংশ্লিষ্ট নির্দিষ্ট ক্ষমতা (যেমন শুধুমাত্র ইনভেন্টরি বা শুধুমাত্র অ্যাকাউন্টস) দেওয়া আবশ্যক। এর ফলে অডিট ট্রেইল অক্ষুণ্ণ থাকে।',
    'manual_ch_staff_ops_s1' => 'সুপার অ্যাডমিন হিসেবে লগইন করে সাইডবারের "People" গ্রুপ থেকে "Employees" সেকশনটি খুলুন।',
    'manual_ch_staff_ops_s2' => '"Create Staff Account" এ ক্লিক করে কর্মচারীর নাম, মোবাইল নম্বর, ইমেইল এবং প্রাথমিক পাসওয়ার্ড প্রদান করুন।',
    'manual_ch_staff_ops_s3' => 'পারমিশন চেকবক্স থেকে কর্মচারীর দায়িত্ব অনুযায়ী সুনির্দিষ্ট ক্ষমতা দিন: Accounts (অর্থ ও পেমেন্ট), Orders (অর্ডার অনুমোদন), Inventory (স্টক মুভমেন্ট), Support (টিকেট সমাধান) ইত্যাদি।',
    'manual_ch_staff_ops_s4' => 'কর্মচারী তার পোর্টালে লগইন করলে শুধুমাত্র তার অনুমোদিত মেনুগুলোই দেখতে পাবেন; অন্য সেকশনগুলো সম্পূর্ণ অদৃশ্য থাকবে।',
    'manual_ch_staff_ops_s5' => 'যদি কোনো ডিলার বা সাব-ডিলার একই সাথে কোম্পানির কর্মচারী হন, তবে সুপার অ্যাডমিন তার অ্যাকাউন্টে "Dual Dashboard" লিংক করে দিতে পারেন।',
    'manual_ch_staff_ops_s6' => 'ডুয়াল অ্যাক্সেসপ্রাপ্ত পার্টনার তার প্রোফাইল মেনু থেকে এক ক্লিকে "Switch to Staff Dashboard" এবং পুনরায় "Switch to Partner Dashboard" করতে পারবেন।',
    'manual_ch_staff_ops_out1' => 'কর্মচারী অ্যাকাউন্ট সিস্টেমে তৈরি হয় এবং প্রতিটি কাজের সাথে সংশ্লিষ্ট কর্মচারীর ডিজিটাল স্বাক্ষর (Audit Log) যুক্ত হয়।',
    'manual_ch_staff_ops_out2' => 'পার্টনার-স্টাফ ডুয়াল সুইচিংয়ের ফলে একজন ব্যবহারকারী তার ব্যক্তিগত ডিলারশিপ এবং অফিসের দায়িত্ব একই লগইনে নিরাপদে চালাতে পারেন।',
    'manual_ch_staff_ops_out3' => 'অপারেশনাল কাজগুলো দ্রুত ও নির্ভুলভাবে সম্পন্ন হয়।',
    'manual_ch_staff_ops_rule1' => 'কোনো সাধারণ কর্মচারী নিজের পারমিশন নিজে বাড়াতে বা পরিবর্তন করতে পারবে না; এটি শুধুমাত্র মালিক/সুপার অ্যাডমিন করতে পারেন।',
    'manual_ch_staff_ops_rule2' => 'আর্থিক পেআউট রেকর্ডের ক্ষেত্রে ভেরিফাইড ব্যাংক ট্রানজেকশন স্লিপ আপলোড করা বাধ্যতামূলক।',
    'manual_ch_staff_ops_rule3' => 'ডুয়াল ড্যাশবোর্ড সুইচ করলেও পার্টনারের নিজস্ব কমিশন ও ব্যক্তিগত ওয়ালেট স্টাফদের কাজের সাথে মিশে যাবে না; হিসাব সম্পূর্ণ আলাদা থাকবে।',
    'manual_ch_staff_ops_t1' => 'প্রতিটি কর্মচারীকে তাদের কাজের দায়িত্ব অনুযায়ী নিয়মিত অডিট করুন এবং চাকরি ছেড়ে দিলে সাথে সাথে অ্যাকাউন্ট ডিয়েক্টিভেট করুন।',
    'manual_ch_staff_ops_t2' => 'ডুয়াল ড্যাশবোর্ড ব্যবহারকারীদের পার্টনার কাজ ও স্টাফ কাজ করার সময় মানসিক সতর্কতা বজায় রাখার পরামর্শ দিন।',
    'manual_ch_staff_ops_warn1' => 'একই কর্মচারীকে একসাথে স্টক রিলিজ এবং ক্যাশ পেআউট উভয় ক্ষমতা দেওয়া পরিহার করুন; দায়িত্ব পৃথকীকরণ বজায় রাখুন।',
    'manual_ch_staff_ops_warn2' => 'কর্মচারীদের লগইন পাসওয়ার্ড কখনো অন্য স্টাফদের সাথে শেয়ার করা যাবে না।',
    'manual_ch_staff_ops_q1' => 'আমি কীভাবে পার্টনার থেকে স্টাফ ড্যাশবোর্ডে যাব?',
    'manual_ch_staff_ops_a1' => 'আপনার অ্যাকাউন্টে ডুয়াল পারমিশন থাকলে উপরের ডানপাশের প্রোফাইল মেনুতে ক্লিক করে "Switch to Staff Dashboard" অপশনটি বেছে নিন।',
    'manual_ch_staff_ops_q2' => 'স্টাফ অ্যাকাউন্টে কি কোনো কিছু ভুল হলে সংশোধন করা যায়?',
    'manual_ch_staff_ops_a2' => 'সুপার অ্যাডমিন যেকোনো অনাকাঙ্ক্ষিত ভুল বা অ্যাকশন অডিট লগ থেকে রিভিউ করে সংশোধন বা রিভার্সাল করতে পারেন।',
    // Chapter 16: website_customization
    'manual_ch_website_customization_title' => '১৬. পাবলিক ওয়েবসাইট সিএমএস, ব্যানার, নোটিশ সার্কুলার ও কাস্টমার ইনকোয়ারি',
    'manual_ch_website_customization_badge' => 'সিএমএস ও পাবলিক কন্টেন্ট',
    'manual_ch_website_customization_summary' => 'মদিনা ওয়েবসাইটের হোমপেজ ব্যানার, হাইলাইট স্লাইডার, জরুরি মূল্য সার্কুলার প্রকাশ, পাবলিক মেসেজ পর্যালোচনা এবং গুগল ম্যাপ লোকেশন কনফিগারেশন।',
    'manual_ch_website_customization_purpose' => 'ওয়েবসাইট সিএমএস মডিউলটি মদিনা ন্যাচারাল কেয়ারের পাবলিক ফেস ও অনলাইন ব্র্যান্ডিং পরিচালনার মূল ড্যাশবোর্ড। এখান থেকে কোনো কোডিং ছাড়াই ওয়েবসাইটের ব্যানার, প্রমোশনাল অফার, অফিশিয়াল সার্কুলার, প্রোডাক্ট ডিসপ্লে এবং গ্রাহকদের পাঠানো যোগাযোগ বার্তা সরাসরি নিয়ন্ত্রণ করা হয়।',
    'manual_ch_website_customization_why' => 'একটি গতিশীল ব্র্যান্ড হিসেবে বাজার পরিস্থিতি, নতুন অফার ও জরুরি নোটিশ তাৎক্ষণিকভাবে গ্রাহক ও ডিলারদের কাছে পৌঁছানো অত্যন্ত গুরুত্বপূর্ণ। এটি ব্র্যান্ডের সুনাম বাড়ায় এবং বিক্রয় বৃদ্ধিতে সহায়তা করে।',
    'manual_ch_website_customization_s1' => 'সাইডবারের "Website" গ্রুপের অধীনে "Website" অথবা "Customization" সেকশনে প্রবেশ করুন।',
    'manual_ch_website_customization_s2' => 'হোমপেজ ব্যানার ট্যাবে ক্লিক করে নতুন অফারের উচ্চ রেজোলিউশনের প্রমোশনাল ব্যানার ছবি আপলোড করুন এবং শিরোনাম ও সাব-টাইটেল লিখুন।',
    'manual_ch_website_customization_s3' => '"Circulars & Notices" ট্যাবে গিয়ে নতুন সার্কুলার তৈরি করুন: নোটিশের শিরোনাম, ক্যাটাগরি এবং বিস্তারিত বডি টেক্সট লিখে "Publish" বাটনে ক্লিক করুন।',
    'manual_ch_website_customization_s4' => 'প্রকাশিত নোটিশ সাথে সাথে تمام ডিলার ও সাব-ডিলারদের "Circulars" পেজে এবং পাবলিক ওয়েবসাইটে প্রদর্শিত হবে।',
    'manual_ch_website_customization_s5' => '"Public Enquiries" ট্যাবে গিয়ে সাধারণ ভিজিটরদের পাঠানো পণ্য অনুসন্ধান বা ডিলারশিপের আবেদনপত্রগুলো পর্যালোচনা করুন।',
    'manual_ch_website_customization_s6' => 'ইনকোয়ারিগুলোর উত্তর দিন অথবা সংশ্লিষ্ট এরিয়া ডিলারের কাছে কাস্টমার লিড হিসেবে ফরোয়ার্ড করুন।',
    'manual_ch_website_customization_out1' => 'ওয়েবসাইটের হোমপেজে নতুন ব্যানার ও অফার লাইভ হয় যা ভিজিটরদের আকৃষ্ট করে।',
    'manual_ch_website_customization_out2' => 'জরুরি সার্কুলার প্রকাশের সাথে সাথে ডিলার পোর্টালে নোটিফিকেশন এলার্ট সৃষ্টি হয়।',
    'manual_ch_website_customization_out3' => 'ইনকোয়ারিগুলোর সঠিক ফলোআপের মাধ্যমে নতুন কাস্টমার ও ডিলারশিপের সেলস বৃদ্ধি পায়।',
    'manual_ch_website_customization_rule1' => 'ব্যানার আপলোড করার সময় সুপারিশকৃত সাইজ (যেমন: 1920x600 পিক্সেল) এবং পরিষ্কার গ্রাফিক্স ব্যবহার করতে হবে।',
    'manual_ch_website_customization_rule2' => 'অফিশিয়াল সার্কুলার প্রকাশের আগে বানান ও তথ্যের সঠিকতা যাচাই করা আবশ্যক; কারণ এটি আইনি বার্তা হিসেবে বিবেচিত হয়।',
    'manual_ch_website_customization_rule3' => 'গ্রাহকদের ইনকোয়ারি বা মেসেজ ২৪ ঘণ্টার মধ্যে রেসপন্স করা কোম্পানির স্ট্যান্ডার্ড এসএলএ (SLA)।',
    'manual_ch_website_customization_t1' => 'উৎসবের মৌসুমে (যেমন ঈদ বা বৈশাখ) আকর্ষণীয় ব্যানার দিয়ে ওয়েবসাইট সাজিয়ে তুলুন।',
    'manual_ch_website_customization_t2' => 'সার্কুলার লেখার সময় গুরুত্বপূর্ণ পয়েন্টগুলো বুলেট আকারে লিখুন যাতে ডিলাররা সহজে বুঝতে পারেন।',
    'manual_ch_website_customization_warn1' => 'কপিরাইট লঙ্ঘন করে এমন কোনো ছবি বা তৃতীয় পক্ষের লোগো ওয়েবসাইটে ব্যবহার করা যাবে না।',
    'manual_ch_website_customization_warn2' => 'ভুল মূল্যের নোটিশ প্রকাশ করলে ব্যবসায়িক বিভ্রান্তি সৃষ্টি হতে পারে; তাই মূল্য নির্ধারণে সতর্ক থাকুন।',
    'manual_ch_website_customization_q1' => 'প্রকাশিত কোনো সার্কুলার কি মুছে ফেলা বা সংশোধন করা যায়?',
    'manual_ch_website_customization_a1' => 'হ্যাঁ, সিএমএস ড্যাশবোর্ড থেকে যেকোনো নোটিশ আন-পাবলিশ, এডিট বা সম্পূর্ণ মুছে ফেলা যায়।',
    'manual_ch_website_customization_q2' => 'ওয়েবসাইটের গুগল ম্যাপের অবস্থান কীভাবে পরিবর্তন করব?',
    'manual_ch_website_customization_a2' => 'Website Customization পেজের "Maps & Contact" সেকশনে আপনার অফিসের গুগল ম্যাপ এমবেড কোড প্রদান করে সেভ করুন।',
    // Chapter 17: support
    'manual_ch_support_title' => '১৭. এন্টারপ্রাইজ সাপোর্ট হেল্পডেস্ক, টিকেট ট্র্যাকিং ও বিরোধ নিষ্পত্তি',
    'manual_ch_support_badge' => 'সাপোর্ট ও বিরোধ নিষ্পত্তি',
    'manual_ch_support_summary' => 'পেমেন্ট, অর্ডার বিলম্ব বা কমিশন সংক্রান্ত সাপোর্ট টিকেট তৈরি, স্ক্রিনশট ও প্রমাণপত্র সংযুক্তি, প্রশাসনিক প্রতিক্রিয়া এবং বিরোধ সমাধানের এসএলএ।',
    'manual_ch_support_purpose' => 'সাপোর্ট ও হেল্পডেস্ক ইঞ্জিনটি যেকোনো পার্টনারের অপারেশনাল বা আর্থিক সমস্যা দ্রুত সমাধানের জন্য প্রতিষ্ঠিত প্রাতিষ্ঠানিক চ্যানেল। সাধারণ ফোনকল বা মেসেজের বাইরে এটি একটি ডিজিটাল টিকেটিং ট্রেইল বজায় রাখে যাতে প্রতিটি অভিযোগের আনুষ্ঠানিক তদন্ত ও সমাধান নিশ্চিত হয়।',
    'manual_ch_support_why' => 'ব্যবসা পরিচালনায় যেকোনো বিভ্রান্তি বা প্রযুক্তিগত সমস্যা দ্রুত নিষ্পত্তি না হলে আর্থিক ক্ষতি হতে পারে। লিখিত টিকেটিং ব্যবস্থার মাধ্যমে অভিযোগের শুরু থেকে সমাধান পর্যন্ত প্রতিটি পদক্ষেপ অডিট করা যায় এবং কোনো অনুরোধ হারিয়ে যায় না।',
    'manual_ch_support_s1' => 'সাইডবার মেনুর "Account" গ্রুপ থেকে "Help" বা "Support" সেকশনে প্রবেশ করুন।',
    'manual_ch_support_s2' => 'যদি কোনো জটিলতা থাকে, তবে প্রথমে এই ম্যানুয়ালের সার্চ বারে সমস্যার কীওয়ার্ড লিখে সংশ্লিষ্ট নিয়মটি জেনে নিন।',
    'manual_ch_support_s3' => 'ম্যানুয়ালে সমাধান না পেলে নিচের "Open Support Ticket" ফর্মে যান।',
    'manual_ch_support_s4' => 'ক্যাটাগরি ড্রপডাউন থেকে সমস্যার ধরন বেছে নিন: Payment Issue, Order Dispatch, Commission Dispute, Technical Bug ইত্যাদি।',
    'manual_ch_support_s5' => 'সংক্ষিপ্ত ও স্পষ্ট একটি বিষয় (Subject) লিখুন এবং বিস্তারিত বিবরণে অর্ডার নম্বর বা ট্রানজেকশন আইডি উল্লেখ করুন।',
    'manual_ch_support_s6' => 'প্রমাণস্বরূপ ব্যাংক স্লিপ, কুরিয়ার চালান বা স্ক্রিনশট ফাইল সংযুক্তি (Attachment) হিসেবে আপলোড করুন।',
    'manual_ch_support_s7' => '"Submit Ticket" এ ক্লিক করুন; সিস্টেম আপনাকে একটি ইউনিক টিকেট আইডি প্রদান করবে।',
    'manual_ch_support_s8' => 'নিচে আপনার পূর্ববর্তী সমস্ত টিকেটের স্ট্যাটাস (Open, In Progress, Resolved) এবং সাপোর্ট টিমের পাঠানো উত্তরগুলো পর্যবেক্ষণ করুন।',
    'manual_ch_support_out1' => 'ডাটাবেসে নতুন সাপোর্ট টিকেট রেকর্ড তৈরি হয় এবং সংশ্লিষ্ট ডিপার্টমেন্টের (অ্যাকাউন্টস বা ফুলফিলমেন্ট) ড্যাশবোর্ডে উচ্চ অগ্রাধিকার সহ প্রদর্শিত হয়।',
    'manual_ch_support_out2' => 'সাপোর্ট অফিসার টিকেটে উত্তর দিলে পার্টনারের ইন্টারফেসে ও ইমেইল/এসএমএসে মেসেজ অ্যালার্ট পৌঁছায়।',
    'manual_ch_support_out3' => 'সমস্যা সমাধান শেষে টিকেটটি "Resolved" হিসেবে বন্ধ হয় এবং পার্টনার ফিডব্যাক দিতে পারেন।',
    'manual_ch_support_rule1' => 'একই সমস্যার জন্য বারবার একাধিক টিকেট খোলা সম্পূর্ণ নিষিদ্ধ; পূর্ববর্তী টিকেটেই মেসেজ দিন।',
    'manual_ch_support_rule2' => 'টিকেট খোলার সময় অশালীন ভাষা বা অবান্তর তথ্য প্রদান করা কঠোরভাবে নিষেধ।',
    'manual_ch_support_rule3' => 'জরুরি পেমেন্ট বা ডিসপ্যাচ সংক্রান্ত বিরোধ অফিসিয়াল কার্যঘণ্টার মধ্যে অগ্রাধিকার ভিত্তিতে নিষ্পত্তি করা হয়।',
    'manual_ch_support_t1' => 'টিকেট লেখার সময় যত বেশি সম্ভব তথ্য (যেমন: TrxID, অর্ডারের তারিখ, ফোন নম্বর) দিন; এতে সমস্যার সমাধান দ্রুত হয়।',
    'manual_ch_support_t2' => 'মোবাইল বা কম্পিউটারের স্পষ্ট স্ক্রিনশট যুক্ত করুন যাতে টেকনিক্যাল টিম মুহূর্তেই সমস্যা শনাক্ত করতে পারে।',
    'manual_ch_support_warn1' => 'সাপোর্ট টিকেটে ভুয়া ব্যাংক স্লিপ বা মিথ্যা তথ্য দিলে অ্যাকাউন্ট সাময়িকভাবে স্থগিত হতে পারে।',
    'manual_ch_support_warn2' => 'টিকেট সমাধান হয়ে গেলে সেটি ক্লোজ করুন যাতে নতুন টিকেট খোলা সহজ হয়।',
    'manual_ch_support_q1' => 'সাপোর্ট টিকেট পাঠালে কতক্ষণের মধ্যে উত্তর পাব?',
    'manual_ch_support_a1' => 'আমাদের সাপোর্ট টিম সাধারণত ১ থেকে ৪ কার্যঘণ্টার মধ্যে প্রাথমিক প্রতিক্রিয়া প্রদান করে এবং সর্বোচ্চ ২৪ ঘণ্টার মধ্যে সমস্যার নিষ্পত্তি করে।',
    'manual_ch_support_q2' => 'ছুটির দিনে কি সাপোর্ট টিকেট কাজ করে?',
    'manual_ch_support_a2' => 'হ্যাঁ, আপনি যেকোনো সময় টিকেট সাবমিট করে রাখতে পারেন। ডিউটি অফিসারগণ জরুরি পেমেন্ট ও ডেলিভারি টিকেট ছুটির দিনেও পর্যবেক্ষণ করেন।',
    // Chapter 18: inventory_branches
    'manual_ch_inventory_branches_title' => '১৮. মাল্টি-ব্রাঞ্চ ইনভেন্টরি, কেন্দ্রীয় ওয়্যারহাউস ও স্টক মুভমেন্ট',
    'manual_ch_inventory_branches_badge' => 'ওয়্যারহাউস ও সাপ্লাই চেইন',
    'manual_ch_inventory_branches_summary' => 'কেন্দ্রীয় গুদাম ও আঞ্চলিক শাখাগুলোর রিয়েল-টাইম স্টক লেভেল, শাখাভিত্তিক কর্মচারী অ্যাসাইনমেন্ট, স্টক ট্রান্সফার অনুমোদন এবং লো-স্টক সতর্কতা।',
    'manual_ch_inventory_branches_purpose' => 'মাল্টি-ব্রাঞ্চ ইনভেন্টরি ইঞ্জিনটি মদিনা ন্যাচারাল কেয়ারের কেন্দ্রীয় ফ্যাক্টরি ওয়্যারহাউস এবং সারাদেশের আঞ্চলিক শাখাগুলোর পণ্য সরবরাহ ও মজুদ নিয়ন্ত্রণের মূল সফটওয়্যার। এটি প্রতিটি আইটেমের ব্যাচ নম্বর, মেয়াদ, ইন-স্টক কোয়ান্টিটি এবং শাখাভিত্তিক বিক্রয় সমন্বয় করে।',
    'manual_ch_inventory_branches_why' => 'সঠিক ইনভেন্টরি ম্যানেজমেন্ট না থাকলে ডিলারদের সময়মতো পণ্য ডেলিভারি দেওয়া সম্ভব হয় না। এই সিস্টেমটি স্বয়ংক্রিয়ভাবে কোনো শাখায় পণ্যের ঘাটতি দেখা দিলে কেন্দ্রীয় ওয়্যারহাউস থেকে দ্রুত স্টক ট্রান্সফারের ব্যবস্থা নিশ্চিত করে।',
    'manual_ch_inventory_branches_s1' => 'ম্যানেজমেন্ট ড্যাশবোর্ডের "Products" গ্রুপ থেকে "Inventory" বা "Branches" সেকশনে প্রবেশ করুন।',
    'manual_ch_inventory_branches_s2' => 'শাখা নির্বাচন ড্রপডাউন থেকে সংশ্লিষ্ট ব্রাঞ্চ (যেমন: ঢাকা কেন্দ্রীয় গুদাম, চট্টগ্রাম শাখা, রাজশাহী হাব ইত্যাদি) বেছে নিন।',
    'manual_ch_inventory_branches_s3' => 'প্রোডাক্ট লিস্টে বর্তমান উপলব্ধ স্টক, সংরক্ষিত (Reserved) স্টক এবং বিক্রয়ের জন্য প্রস্তুত পরিমাণের তালিকা দেখুন।',
    'manual_ch_inventory_branches_s4' => 'এক শাখা থেকে অন্য শাখায় পণ্য পাঠানোর জন্য "Initiate Stock Transfer" বাটনে ক্লিক করুন।',
    'manual_ch_inventory_branches_s5' => 'প্রেরক শাখা, প্রাপক শাখা, পণ্যের তালিকা এবং পরিমাণের সংখ্যা দিয়ে চালান তৈরি করুন।',
    'manual_ch_inventory_branches_s6' => 'প্রাপক শাখা পণ্য হাতে পাওয়ার পর ফিজিক্যাল কাউন্ট মিলিয়ে "Confirm Stock Receipt" বাটনে ক্লিক করলে ডাটাবেসে স্টক ট্রান্সফার সম্পন্ন হবে।',
    'manual_ch_inventory_branches_s7' => 'কোনো পণ্যের স্টক নির্দিষ্ট সীমার নিচে নেমে গেলে সিস্টেমের স্বয়ংক্রিয় "Low Stock Alert" লাল ব্যাজ আকারে প্রদর্শিত হবে।',
    'manual_ch_inventory_branches_out1' => 'প্রেরক শাখার স্টক থেকে পণ্য বিয়োগ হয় এবং ট্রানজিট লেজারে জমা হয়; প্রাপক নিশ্চিত করলে সেখানে স্টক ক্রেডিট হয়।',
    'manual_ch_inventory_branches_out2' => 'ডিলাররা ক্যাটালগে সর্বদা রিয়েল-টাইম সঠিক স্টক পরিস্থিতি দেখতে পান।',
    'manual_ch_inventory_branches_out3' => 'ইনভেন্টরি ডেপ্রিসিয়েশন, ড্যামেজ বা মেয়াদোত্তীর্ণ পণ্যের স্পষ্ট অডিট রেকর্ড সংরক্ষিত থাকে।',
    'manual_ch_inventory_branches_rule1' => 'শারীরিক গণনা (Physical Verification) ছাড়া সিস্টেমে স্টক সমন্বয় বা ট্রান্সফার অনুমোদন করা যাবে না।',
    'manual_ch_inventory_branches_rule2' => 'কোনো শাখা ঋণাত্মক (Negative) স্টকে পণ্য বিক্রি বা ডিসপ্যাচ করতে পারবে না; সিস্টেম এটি কঠোরভাবে ব্লক করে।',
    'manual_ch_inventory_branches_rule3' => 'প্রতিটি স্টক স্থানান্তরের সাথে দায়িত্বপ্রাপ্ত ওয়্যারহাউস অফিসারের ডিজিটাল স্বাক্ষর সংরক্ষিত থাকবে।',
    'manual_ch_inventory_branches_t1' => 'সাপ্তাহিক ভিত্তিতে ওয়্যারহাউসের ফিজিক্যাল গণনার সাথে সফটওয়্যারের স্টক কাউন্ট মিলিয়ে নিন।',
    'manual_ch_inventory_branches_t2' => 'শীর্ষ বিক্রীত পণ্যগুলোর জন্য বাফার স্টক বজায় রাখুন যাতে কোনো বড় অর্ডারে বিলম্ব না ঘটে।',
    'manual_ch_inventory_branches_warn1' => 'প্রাপক শাখার নিশ্চিতকরণ ব্যতিরেকে স্টক ট্রান্সফারকে সম্পন্ন ধরা যাবে না; ট্রানজিটে ক্ষতি হলে তা চিহ্নিত করুন।',
    'manual_ch_inventory_branches_warn2' => 'স্টকে গরমিল থাকলে অবিলম্বে অডিট ইনভেস্টিগেশন শুরু করুন।',
    'manual_ch_inventory_branches_q1' => 'ডিলাররা কি সরাসরি শাখা থেকে পণ্য তুলে নিতে পারে?',
    'manual_ch_inventory_branches_a1' => 'হ্যাঁ! অর্ডার দেওয়ার সময় সেলফ-পিকআপ অপশন নির্বাচন করলে সংশ্লিষ্ট আঞ্চলিক শাখা থেকে সরাসরি চালান গ্রহণ করা যায়।',
    'manual_ch_inventory_branches_q2' => 'স্টক ট্রান্সফার করতে কত সময় লাগে?',
    'manual_ch_inventory_branches_a2' => 'চালান তৈরি সাথে সাথে সিস্টেমে "In-Transit" দেখায় এবং পণ্য পৌঁছানোর পর প্রাপক শাখা গ্রহণ নিশ্চিত করলে সাথে সাথে স্টক যোগ হয়।',
    // Chapter 19: payment_claims_gateways
    'manual_ch_payment_claims_gateways_title' => '১৯. পেমেন্ট চ্যানেল, ট্রানজেকশন আইডি (TrxID) ও ম্যানুয়াল ব্যাংক রসিদ যাচাই',
    'manual_ch_payment_claims_gateways_badge' => 'পেমেন্ট চ্যানেল ও যাচাই',
    'manual_ch_payment_claims_gateways_summary' => 'বিকাশ, নগদ, রকেট ও ব্যাংক অ্যাকাউন্টে টাকা জমার পর TrxID সাবমিট, ডিপোজিট স্লিপ আপলোড, অ্যাকাউন্টস ডেস্ক কর্তৃক ম্যানুয়াল যাচাই ও অটো-রিকনসিলিয়েশন।',
    'manual_ch_payment_claims_gateways_purpose' => 'পেমেন্ট ক্লেইম ইঞ্জিনটি পার্টনারদের কোম্পানিকে টাকা পরিশোধের বৈধ প্রমাণ ডিজিটাল উপায়ে জমা দেওয়ার গেটওয়ে। এটি বিকাশ, নগদ, রকেটের মতো মোবাইল ব্যাংকিং এবং সব ধরনের বাণিজ্যিক ব্যাংকের মাধ্যমে পাঠানো টাকার ট্রানজেকশন রেফারেন্স ও ব্যাংক স্লিপ সমন্বয় করে।',
    'manual_ch_payment_claims_gateways_why' => 'অনলাইনে প্রতারণামূলক পেমেন্ট বা ভুল একাউন্টে টাকা পাঠানো রোধ করতে এই বহুস্তরীয় যাচাই ব্যবস্থা অপরিহার্য। এটি কোম্পানির অ্যাকাউন্টস টিমকে শতভাগ নিশ্চিত করে প্রতিটি অর্ডারের টাকা সঠিক ব্যাংক অ্যাকাউন্টে জমা হয়েছে কিনা তা প্রমাণ করার আইনি ভিত্তি দেয়।',
    'manual_ch_payment_claims_gateways_s1' => 'যেকোনো পেন্ডিং অর্ডারে প্রবেশ করে "Submit Payment Claim" বাটনে ক্লিক করুন।',
    'manual_ch_payment_claims_gateways_s2' => 'কোম্পানির অনুমোদিত পেমেন্ট একাউন্ট তালিকা থেকে আপনি কোন অ্যাকাউন্টে টাকা পাঠিয়েছেন তা বেছে নিন (যেমন: বিকাশ মার্চেন্ট, ডাচ-বাংলা ব্যাংক, সিটি ব্যাংক ইত্যাদি)।',
    'manual_ch_payment_claims_gateways_s3' => 'আপনার পাঠানো সঠিক টাকার পরিমাণ (Amount) লিখুন।',
    'manual_ch_payment_claims_gateways_s4' => 'মোবাইল ব্যাংকিংয়ের ক্ষেত্রে প্রাপ্ত ৮-১০ অক্ষরের ট্রানজেকশন আইডি (TrxID) এবং ব্যাংকের ক্ষেত্রে ডিপোজিট স্লিপ নম্বর প্রদান করুন।',
    'manual_ch_payment_claims_gateways_s5' => 'ব্যাংকের জমার রসিদ বা মোবাইল ট্রানজেকশনের স্পষ্ট স্ক্রিনশট ফাইল অ্যাটাচমেন্ট হিসেবে আপলোড করুন।',
    'manual_ch_payment_claims_gateways_s6' => '"Submit Claim" এ ক্লিক করুন; স্ট্যাটাস তাৎক্ষণিকভাবে "Pending Verification" হবে।',
    'manual_ch_payment_claims_gateways_s7' => 'কোম্পানির ফাইন্যান্স ডেস্ক ব্যাংক স্টেটমেন্ট চেক করে পেমেন্ট মিলিয়ে নিলে আপনার অর্ডারের বকেয়া শূন্য হবে এবং অর্ডার ডিসপ্যাচের জন্য অনুমোদিত হবে।',
    'manual_ch_payment_claims_gateways_out1' => 'পেমেন্ট ক্লেইমটি ডাটাবেসে নিবন্ধিত হয় এবং সংশ্লিষ্ট TrxID ইউনিক হিসেবে লক হয় যাতে একই TrxID দুইবার ব্যবহার না করা যায়।',
    'manual_ch_payment_claims_gateways_out2' => 'ফাইন্যান্স ডেস্কে পেমেন্ট যাচাইয়ের অ্যালার্ট পৌঁছায়।',
    'manual_ch_payment_claims_gateways_out3' => 'অনুমোদন পাওয়ার সাথে সাথে অর্ডারের স্ট্যাটাস "Paid" হয় এবং ইনভয়েসের ব্যালেন্স আপডেট হয়।',
    'manual_ch_payment_claims_gateways_rule1' => 'শুধুমাত্র কোম্পানির নির্ধারিত অফিসিয়াল ব্যাংক অ্যাকাউন্ট ও মার্চেন্ট নম্বরে টাকা পাঠাতে হবে; কোনো ব্যক্তির ব্যক্তিগত নম্বরে টাকা পাঠানো সম্পূর্ণ নিষিদ্ধ।',
    'manual_ch_payment_claims_gateways_rule2' => 'একটি ট্রানজেকশন আইডি (TrxID) শুধুমাত্র একটি অর্ডারের জন্যই ব্যবহারযোগ্য।',
    'manual_ch_payment_claims_gateways_rule3' => 'পেমেন্ট করার পর সর্বোচ্চ ২৪ ঘণ্টার মধ্যে সিস্টেমে ক্লেইম সাবমিট করতে হবে।',
    'manual_ch_payment_claims_gateways_t1' => 'ব্যাংকে টাকা জমার পর ক্যাশ কাউন্টারের সীল ও স্বাক্ষরযুক্ত ডিপোজিট স্লিপটি সযত্নে সংরক্ষণ করুন।',
    'manual_ch_payment_claims_gateways_t2' => 'মোবাইলে পেমেন্ট করার সময় TrxID কপি করে সরাসরি পেস্ট করুন যাতে কোনো অক্ষর ভুল না হয়।',
    'manual_ch_payment_claims_gateways_warn1' => 'ভুয়া, এডিট করা বা অন্য কারো ট্রানজেকশন আইডি ব্যবহার করা আইনত দণ্ডনীয় অপরাধ; এরূপ ক্ষেত্রে অ্যাকাউন্ট সাথে সাথে ব্লক করা হবে।',
    'manual_ch_payment_claims_gateways_warn2' => 'কোম্পানির অফিশিয়াল অ্যাপ বা পোর্টালে উল্লেখিত অ্যাকাউন্ট ছাড়া অন্য কোথাও টাকা পাঠাবেন না।',
    'manual_ch_payment_claims_gateways_q1' => 'আমি ভুল TrxID দিয়ে ফেলেছি, এখন কী করণীয়?',
    'manual_ch_payment_claims_gateways_a1' => 'তাৎক্ষণিকভাবে হেল্প সেকশন থেকে সাপোর্ট টিকেট খুলে সঠিক TrxID ও ব্যাংক স্লিপের ছবি যুক্ত করে দিন। ফাইন্যান্স টিম ম্যানুয়ালি আপডেট করে দেবে।',
    'manual_ch_payment_claims_gateways_q2' => 'পেমেন্ট ভেরিফাই হতে কত সময় লাগে?',
    'manual_ch_payment_claims_gateways_a2' => 'অফিসিয়াল কার্যঘণ্টার মধ্যে সাধারণত ৩০ মিনিট থেকে ২ ঘণ্টার মধ্যে ব্যাংক স্টেটমেন্ট চেক করে পেমেন্ট অনুমোদন করা হয়।',
    // Chapter 20: commission_simulator
    'manual_ch_commission_simulator_title' => '২০. পলিসি স্যান্ডবক্স, স্ট্রেস-টেস্টিং ও কমিশন সিমুলেশন টুল',
    'manual_ch_commission_simulator_badge' => 'পলিসি সিমুলেটর',
    'manual_ch_commission_simulator_summary' => 'লাইভ ডাটাবেসে প্রভাব না ফেলে নতুন কমিশন পলিসি ও রেট পরিবর্তন পরীক্ষা করা, সম্ভাব্য ডিস্ট্রিবিউটর পেআউট সিমুলেশন এবং ঝুঁকি বিশ্লেষণ।',
    'manual_ch_commission_simulator_purpose' => 'কমিশন সিমুলেটর ও পলিসি স্যান্ডবক্স হলো কোম্পানির নির্বাহী আর্থিক নীতিনির্ধারকদের জন্য প্রস্তুতকৃত একটি শক্তিশালী মডেলিং টুল। এর মাধ্যমে কোনো নতুন কমিশন রেট বা পদবী পলিসি বাস্তবে চালু করার পূর্বে অতীত ও সম্ভাব্য ভবিষ্যৎ সেলস ডাটার ওপর প্রয়োগ করে ফলাফল পরীক্ষা করা যায়।',
    'manual_ch_commission_simulator_why' => 'হুট করে কমিশন রেট বাড়ালে বা পরিবর্তন করলে কোম্পানির পরিচালন মুনাফায় ঝুঁকি তৈরি হতে পারে। এই সিমুলেটরের সাহায্যে শতভাগ নিশ্চিত হওয়া যায় যে নতুন পলিসিতেও কোম্পানির ৬০% মূলধন সম্পূর্ণ সুরক্ষিত থাকবে এবং ডিলারদের আয় যৌক্তিক থাকবে।',
    'manual_ch_commission_simulator_s1' => 'সুপার অ্যাডমিন বা ফাইন্যান্স হেড হিসেবে সাইডবারের "Dealer Commission" গ্রুপ থেকে "Simulator" সেকশনটি খুলুন।',
    'manual_ch_commission_simulator_s2' => 'সিমুলেশন কন্ট্রোলারে প্রস্তাবিত পরিবর্তনগুলো দিন: যেমন ডিরেক্ট স্পনসর কমিশন %, জেনারেশন বোনাস হার, বা রয়্যালটি পুলের শতাংশ।',
    'manual_ch_commission_simulator_s3' => 'পরীক্ষার জন্য একটি সময়কাল বেছে নিন (যেমন: "গত ৩ মাসের বাস্তব সেলস ডাটা" অথবা "প্রজেক্টেড সেলস ভলিউম")।',
    'manual_ch_commission_simulator_s4' => '"Run Policy Simulation" বাটনে ক্লিক করুন; ইঞ্জিন লাইভ ডাটাবেসকে স্পর্শ না করে মেমোরিতে সম্পূর্ণ হিসাব সম্পন্ন করবে।',
    'manual_ch_commission_simulator_s5' => 'সিমুলেশন রিপোর্টে কোম্পানির প্রজেক্টেড পরিচালন মার্জিন, ডিলারদের গড় আয় এবং টোটাল পেআউট লায়াবিলিটি চার্ট বিশ্লেষণ করুন।',
    'manual_ch_commission_simulator_s6' => 'যদি ফলাফল সন্তোষজনক ও লাভজনক হয়, তবেই নতুন পলিসি ড্রাফট হিসেবে সেভ করে বোর্ডে অনুমোদনের জন্য পেশ করুন।',
    'manual_ch_commission_simulator_out1' => 'পলিসি পরিবর্তনের সম্ভাব্য সমস্ত আর্থিক প্রভাবের পরিষ্কার গ্রাফ ও পূর্বাভাস পাওয়া যায়।',
    'manual_ch_commission_simulator_out2' => 'লাইভ সিস্টেমে কোনো ধরনের আর্থিক বিশৃঙ্খলা বা ভুল এন্ট্রি হওয়ার ঝুঁকি সম্পূর্ণ শূন্য থাকে।',
    'manual_ch_commission_simulator_out3' => 'প্রতিষ্ঠান একটি দীর্ঘমেয়াদী স্থিতিশীল ও লাভজনক আর্থিক নীতিতে পরিচালিত হয়।',
    'manual_ch_commission_simulator_rule1' => 'সিমুলেটর থেকে প্রাপ্ত ফলাফল সম্পূর্ণ তাত্ত্বিক মডেলিং; এটি অনুমোদিত না হওয়া পর্যন্ত বাস্তবে কোনো অ্যাকাউন্টে প্রভাব ফেলে না।',
    'manual_ch_commission_simulator_rule2' => 'শুধুমাত্র সুপার অ্যাডমিন ও ফাইন্যান্স ডিরেক্টর এই টুলটি পরিচালনা করতে পারেন।',
    'manual_ch_commission_simulator_rule3' => 'সিমুলেশন চালানোর সময় সার্ভার রিসোর্সের সর্বোচ্চ সুরক্ষা নিশ্চিত করতে অপ্টিমাইজড অ্যালগরিদম ব্যবহৃত হয়।',
    'manual_ch_commission_simulator_t1' => 'যেকোনো নতুন উৎসব বোনাস বা ইনসেন্টিভ ঘোষণা করার আগে সিমুলেটরে অন্তত ৩টি ভিন্ন দৃশ্যপট (Best case, Expected case, Worst case) পরীক্ষা করুন।',
    'manual_ch_commission_simulator_t2' => 'অতীতের মন্দা মৌসুমের ডাটার ওপর স্ট্রেস-টেস্ট চালান যাতে বোঝা যায় কঠিন পরিস্থিতিতেও সিস্টেম সচল থাকবে কিনা।',
    'manual_ch_commission_simulator_warn1' => 'সিমুলেটরের পরীক্ষামূলক রেজাল্টকে কখনো ডিলারদের সামনে অফিশিয়াল রেট হিসেবে প্রচার করবেন না।',
    'manual_ch_commission_simulator_warn2' => 'বোর্ডের লিখিত অনুমোদন ছাড়া সিমুলেটরের কোনো প্যারামিটার লাইভ প্রোডাকশনে প্রয়োগ করা সম্পূর্ণ নিষিদ্ধ।',
    'manual_ch_commission_simulator_q1' => 'সিমুলেশন চালালে কি লাইভ ডিলারদের ব্যালেন্সে কোনো পরিবর্তন হয়?',
    'manual_ch_commission_simulator_a1' => 'না, কখনো নয়। সিমুলেটর একটি সম্পূর্ণ আইসোলেটেড ভার্চুয়াল স্যান্ডবক্সে চলে; লাইভ ডাটাবেসের কোনো তথ্যে হাত দেওয়া হয় না।',
    'manual_ch_commission_simulator_q2' => 'নতুন পলিসি কখন থেকে কার্যকর করা যায়?',
    'manual_ch_commission_simulator_a2' => 'বোর্ড অনুমোদনের পর পলিসি ম্যানেজার থেকে নির্ধারিত তারিখে (যেমন পরবর্তী মাসের ১ তারিখ) নতুন পলিসি কার্যকর করা যায়।',
    'tour_welcome_badge' => 'মদিনা ন্যাচারাল কেয়ারে স্বাগতম',
    'tour_welcome_title' => 'আপনার ইন্টারেক্টিভ লাইভ ট্যুর ও ইউজার ম্যানুয়াল',
    'tour_welcome_subtitle' => 'ইন্টারেক্টিভ স্পটলাইট ও নির্দেশিকার মাধ্যমে প্রধান এবং খুঁটিনাটি সকল ফিচার সম্পর্কে বিস্তারিত জেনে নিন।',
    'tour_welcome_pillar_ops' => 'অর্ডার ও পাইকারি কেনাকাটা',
    'tour_welcome_pillar_ops_desc' => 'ক্যাটালগ থেকে প্রোডাক্ট বাছাই করুন, ক্রয়ের অনুরোধ দিন, ডেলিভারি ট্র্যাক করুন এবং ইনভয়েস ডাউনলোড করুন।',
    'tour_welcome_pillar_fin' => 'রিয়েল-টাইম কমিশন ও ওয়ালেট',
    'tour_welcome_pillar_fin_desc' => '৪০% কমিশন বণ্টন, স্বচ্ছ লেজার এন্ট্রি, র‍্যাঙ্ক ও রয়্যালটি এবং দ্রুত উত্তোলন পর্যবেক্ষণ করুন।',
    'tour_welcome_pillar_help' => 'সার্চযোগ্য ম্যানুয়াল ও লাইভ ট্যুর',
    'tour_welcome_pillar_help_desc' => '১৭টি বিস্তারিত অধ্যায়, সার্চ সুবিধা ও টিপসসহ যেকোনো সময় হেডার থেকে পুনরায় ব্যবহারযোগ্য।',
    'tour_btn_start_tour' => 'ইন্টারেক্টিভ ট্যুর শুরু করুন',
    'tour_btn_open_manual' => 'সম্পূর্ণ ইউজার ম্যানুয়াল খুলুন',
